INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Yorkshire Precision Engineering Ltd', 'Yorkshire Precision Engineering Ltd (YPEL) is a subcontract CNC machining company based in Keighley, West Yorkshire, specialising in the manufacture of precision CNC turned and milled parts in a wide range of materials. They operate modern premises with multi-axis sliding head and fixed head lathes, producing components from 1mm up to 65mm diameter bar fed and 300mm diameter billets. The company holds UKAS ISO 9001 certification and serves industries including oil and gas, pharmaceutical, marine, and food production.', '{"company_type":"CNC Machining","website_url":"https://www.ypel.co.uk","location":"Keighley, West Yorkshire, UK","certifications":["ISO 9001"],"capabilities":["CNC Turning","CNC Milling","Sliding Head Machining","Multi-Axis Machining","Clean Room Assembly"],"industries":["Oil & Gas","Pharmaceutical","Marine","Food Production","Agriculture","Chemical Processing"],"lead_time":null,"min_order":null,"employees":"10-49","established":2001,"materials":["Aluminium","Stainless Steel","Carbon Steel","Alloy Steel","Copper","Brass","Engineering Plastics"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Breckland Precision Engineering Ltd', 'Breckland Precision Engineering Ltd is a subcontract CNC machining specialist based in Fakenham, Norfolk with over 20 years of experience manufacturing custom machined components. The company offers CNC milling and turning services with fast turnaround times and competitive pricing, serving customers nationally and internationally. They hold ISO 9001 and ISO 45001 certifications.', '{"company_type":"CNC Machining","website_url":"https://www.bpe-cncprecision.co.uk","location":"Fakenham, Norfolk, UK","certifications":["ISO 9001","ISO 45001"],"capabilities":["CNC Milling","CNC Turning","Custom Machined Components"],"industries":["Food Manufacturing","Oil & Gas","Pharmaceutical","Automotive"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'T&G Engineering Holdings Limited', 'T&G Engineering is a precision subcontract machining company established in 1975, based in West Byfleet, Surrey, serving worldwide customers across aerospace, automotive, pharmaceutical, and medical sectors. They operate 5-axis CNC machining with lights-out capability, along with wire erosion, spark erosion, and CNC grinding services. The company exports over 50% of all components to European and worldwide markets.', '{"company_type":"CNC Machining","website_url":"https://www.tgengineering.co.uk","location":"West Byfleet, Surrey, UK","certifications":["ISO 9001"],"capabilities":["5-Axis CNC Machining","CNC Turning","CNC Milling","CNC Grinding","Wire EDM","Spark Erosion","3D CAD Design"],"industries":["Aerospace","Automotive","Pharmaceutical","Medical","Special Purpose Machinery"],"lead_time":null,"min_order":null,"employees":"50-99","established":1975,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'TJW Precision Engineering Ltd', 'TJW Precision Engineering Ltd is a total one-stop subcontract machining company founded in 1983 with dual sites in Dursley, Gloucestershire and Stourbridge, West Midlands. The Dursley facility holds AS9100 Rev D certification and the Stourbridge site holds ISO 9001:2015, with customer approvals from Airbus UK, Goodrich Actuation Systems, and GKN Aerospace. Their capabilities include 5-axis CNC machining, wire EDM, water jet cutting, CNC grinding, and in-house anodising.', '{"company_type":"CNC Machining","website_url":"https://www.tjwprecision.co.uk","location":"Dursley, Gloucestershire / Stourbridge, West Midlands, UK","certifications":["AS9100 Rev D","ISO 9001:2015","UVDB Silver"],"capabilities":["5-Axis CNC Machining","CNC Milling","CNC Turning","Wire EDM","Spark Erosion","Water Jet Cutting","CNC Grinding","Anodising"],"industries":["Aerospace","Automotive","Oil & Gas","Nuclear","Medical","Metrology"],"lead_time":null,"min_order":null,"employees":"50-99","established":1983,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nerc Precision Engineering Ltd', 'Nerc Precision Engineering Ltd is an ISO 9001:2015 accredited CNC machining company based in Longhope, Gloucestershire, specialising in 5-axis CNC milling and turning for prototypes, small, and medium batch work. Founded in 2018, the company operates state-of-the-art 5-axis CNC machines capable of producing complex parts to tight tolerances for aerospace, defence, and medical sectors. They offer surface treatments and finishing through a trusted supplier network.', '{"company_type":"CNC Machining","website_url":"https://www.nercengineering.co.uk","location":"Longhope, Gloucestershire, UK","certifications":["ISO 9001:2015"],"capabilities":["5-Axis CNC Milling","CNC Turning","Prototype Machining","Small Batch Production","Surface Finishing"],"industries":["Aerospace","Defence","Oil & Gas","Medical"],"lead_time":null,"min_order":null,"employees":"1-9","established":2018,"materials":["Medical-Grade Metals","Engineering Plastics"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pro-Mil Engineering Limited', 'Pro-Mil Engineering Limited is a precision subcontract large CNC machining specialist located in Sutton Coldfield, West Midlands, capable of handling engineering components up to 50 tonnes. The company holds ISO 9001 and ISO 14001 certifications and serves industries including aerospace, defence, oil and gas, marine, and satellite communications. They offer CAD/CAM services, composite machining, and integrated management systems alongside their core large-format precision milling capability.', '{"company_type":"CNC Machining","website_url":"https://www.pro-mil.co.uk","location":"Sutton Coldfield, West Midlands, UK","certifications":["ISO 9001","ISO 14001"],"capabilities":["Large CNC Milling","CNC Machining up to 50 Tonnes","CAD/CAM","Composite Machining"],"industries":["Aerospace","Defence","Oil & Gas","Marine","Power Generation","Satellite Communications"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Standish Engineering Co Ltd', 'Standish Engineering Co Ltd is a precision CNC machining company founded in 1950, based in Standish, Lancashire, with extensive experience supplying components to pharmaceutical, aerospace, and rail industries. The company holds ISO 9001:2015 and RISQS (Railway Industry Supplier Qualification Scheme) certifications, and has supplied clients including BAE Systems, Virgin Trains, and GE Oil and Gas. They offer CNC turning, milling, and batch or one-off prototype machining.', '{"company_type":"CNC Machining","website_url":"https://www.standishengineering.co.uk","location":"Standish, Lancashire, UK","certifications":["ISO 9001:2015","RISQS"],"capabilities":["CNC Turning","CNC Milling","CNC Machining","Prototype Machining","Batch Production"],"industries":["Pharmaceutical","Aerospace","Rail","Automotive"],"lead_time":null,"min_order":null,"employees":"10-49","established":1950,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oracle Precision Limited', 'Oracle Precision Limited is a precision engineering company incorporated in 2007 and based in Wath-Upon-Dearne, Rotherham, South Yorkshire, holding AS9100 aerospace accreditation. They specialise in 5-axis CNC machining, sliding head lathe operations, prototype development, and CMM inspection services across aerospace, medical, oil and gas, and Ministry of Defence sectors. The company emphasises a partnership approach and right-first-time manufacturing philosophy.', '{"company_type":"CNC Machining","website_url":"https://oracle-precision.co.uk","location":"Rotherham, South Yorkshire, UK","certifications":["AS9100"],"capabilities":["5-Axis CNC Machining","CNC Turning","Sliding Head Machining","Prototype Development","CAD/CAM","CMM Inspection"],"industries":["Aerospace","Medical","Oil & Gas","Defence","Marine","Renewables"],"lead_time":null,"min_order":null,"employees":"10-49","established":2007,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'RDL Technologies Ltd', 'RDL Technologies Ltd is a precision engineering company based in Leicester with over 25 years of experience offering CNC turning, sliding head machining, CNC milling, and twin spindle machining services. The company provides complete finishing and assembly services including laser marking, part cleaning, and component assembly. They hold ISO 9001 certification and serve customers throughout the UK Midlands and nationwide.', '{"company_type":"CNC Machining","website_url":"https://www.rdltechnologies.co.uk","location":"Leicester, Leicestershire, UK","certifications":["ISO 9001"],"capabilities":["CNC Turning","CNC Milling","Sliding Head Machining","Twin Spindle Machining","Laser Marking","Assembly"],"industries":["General Engineering","Automotive","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Batchflow Engineering Ltd', 'Batchflow Engineering Ltd is a family-owned ISO 9001:2015 accredited subcontract CNC machining company founded in 1986, based near Warwick in Warwickshire. The company operates over 20 CNC machining centres running 24 hours, including Nakamura twin-spindle, Doosan CNC turning, Star and Citizen sliding head, and XYZ milling technology, with bar capacity to 65mm. They are a member of the British Turned Parts Manufacturers Association and serve motorsport (F1, Touring Cars, WRC), defence, hydraulics, and automotive sectors.', '{"company_type":"CNC Machining","website_url":"https://www.batchflow.co.uk","location":"Warwick, Warwickshire, UK","certifications":["ISO 9001:2015"],"capabilities":["CNC Turning","CNC Milling","Sliding Head Machining","Twin Spindle Machining","One-Hit Machining"],"industries":["Motorsport","Defence","Hydraulics","Automotive","Electronics"],"lead_time":null,"min_order":null,"employees":"10-49","established":1986,"materials":["All materials from plastics to titanium"],"key_equipment":["Nakamura twin-spindle","Doosan CNC turning","Star sliding head","Citizen sliding head","XYZ milling"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wilsons Engineering Ltd', 'Wilsons Engineering Ltd is a precision CNC machining company established in 1952 and based in Warmley, Bristol, holding ISO 9001, AS9100D, and ISO 9001:2015 certifications. The company offers a comprehensive range of services including 5-axis CNC machining, CNC turning and milling, grinding, honing, and CNC CMM inspection, serving rail, aerospace, defence, nuclear, and automotive industries. They supply precision components to clients across Bristol, Bath, Gloucester, Swindon, and the wider UK.', '{"company_type":"CNC Machining","website_url":"https://www.wileng.co.uk","location":"Warmley, Bristol, UK","certifications":["ISO 9001","AS9100D","ISO 9001:2015"],"capabilities":["CNC Turning","CNC Milling","5-Axis Machining","Grinding","Honing","CMM Inspection"],"industries":["Rail","Aerospace","Defence","Nuclear","Automotive","Hydraulics","Electronics"],"lead_time":null,"min_order":null,"employees":"50-99","established":1952,"materials":["Aluminium","Mild Steel","Stainless Steel","Copper","Brass","Duplex","Titanium","Steel Alloys","Engineering Plastics"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Manchester Automatic Machining', 'Manchester Automatic Machining (MAM) is a family-run precision engineering company established in 1948 and based in Sale, Cheshire, with over 70 years of experience manufacturing small CNC turned parts. The company invests in the latest turning technology including LFV (Low Frequency Vibration) turning technology and operates sliding head machining for miniature components. They serve companies across all industry sectors and produce components from brass, copper, stainless steel, aluminium, steel, and plastics.', '{"company_type":"CNC Machining","website_url":"https://www.manchestermachining.co.uk","location":"Sale, Cheshire, UK","certifications":null,"capabilities":["CNC Turning","Sliding Head Machining","Miniature Machining","Precision Turned Parts"],"industries":["General Engineering","Electronics","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":1948,"materials":["Brass","Copper","Stainless Steel","Aluminium","Steel","Plastics"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
