INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Contract Solutions Scotland Ltd', 'Contract Solutions Scotland Ltd is a precision CNC machining company founded in 2006 and based in Cupar, Fife, Scotland, holding AS9100D, ISO 9001:2015, and JOSCAR certifications. The company operates an extensive machine shop including 12 Matsuura CNC machining centres, DMG Mill-Turn equipment, Mori Seiki CNC lathes, and Star sliding head machines, serving aerospace, defence, space satellite, medical, and oil and gas industries. They supply customers in the UK, USA, Europe, and the Far East.', '{"company_type":"CNC Machining","website_url":"https://www.cssprecision.com","location":"Cupar, Fife, Scotland, UK","certifications":["AS9100D","ISO 9001:2015","JOSCAR"],"capabilities":["5-Axis CNC Milling","CNC Turning","Multi-Axis Turning","Sliding Head Machining","Wire EDM","Etching","Coating"],"industries":["Aerospace","Defence","Space Satellite","Medical","Oil & Gas","Renewables","Motorsport"],"lead_time":null,"min_order":null,"employees":"50-99","established":2006,"materials":["Plastics","High-Temperature Alloys"],"key_equipment":["Matsuura CNC machining centres","DMG DMU 40","DMG NTX 2000 Mill Turn","Mori Seiki CNC lathes","Star SR32J sliding head"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Falcon Precision Engineers', 'Falcon Precision Engineers is a UKAS-registered ISO 9001:2015 subcontract CNC machining company based in Bury, Lancashire, with over 35 years of experience specialising in large, high-quality turned and milled parts. The company provides CNC and manual turning, CNC and manual milling, boring, drilling, grinding, and specialist machining services. They serve aerospace, nuclear, industrial, and mining sectors.', '{"company_type":"CNC Machining","website_url":"https://fpengineers.co.uk","location":"Bury, Lancashire, UK","certifications":["ISO 9001:2015"],"capabilities":["CNC Turning","Manual Turning","CNC Milling","Manual Milling","Boring","Drilling","Grinding"],"industries":["Aerospace","Nuclear","Industrial","Mining"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pulse Engineering', 'Pulse Engineering is a UKAS-approved ISO 9001 precision CNC machining company based in Wooburn Green, High Wycombe, Buckinghamshire, offering high-accuracy machining of complex components. Their capabilities include CNC milling, CNC turning, 5-axis machining, grinding, and manual machining, with client references including Ferrari, Aston Martin, Siemens, and Safran. The company emphasises material knowledge and suitability for specific applications.', '{"company_type":"CNC Machining","website_url":"https://www.pulse-engineering.co.uk","location":"Wooburn Green, High Wycombe, Buckinghamshire, UK","certifications":["ISO 9001"],"capabilities":["CNC Milling","CNC Turning","5-Axis Machining","Grinding","Manual Machining"],"industries":["Aerospace","Automotive","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

