VALUES ('Products', 'Manufacturer', 'Thomas Brown Engineering Ltd', 'Thomas Brown Engineering Ltd is an independent, family-run precision CNC machining company founded in 1982 and based in Huddersfield, West Yorkshire, holding both AS9100D and ISO 9001:2015 certifications. They specialise in CNC turning and milling, prototype development, tool room and grinding work, and CMM inspection, with material capabilities spanning plastics to exotic alloys. Their sectors include aerospace, defence, automotive, medical, nuclear, food and drink, and oil and gas.', '{"company_type":"CNC Machining","website_url":"https://www.thomas-brown-engineering.co.uk","location":"Huddersfield, West Yorkshire, UK","certifications":["AS9100D","ISO 9001:2015"],"capabilities":["CNC Turning","CNC Milling","Prototype Development","Grinding","CMM Inspection"],"industries":["Aerospace","Defence","Automotive","Food & Drink","Medical","Nuclear","Oil & Gas"],"lead_time":null,"min_order":null,"employees":"10-49","established":1982,"materials":["Plastics","Exotic Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

