INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'MP Engineering (Chippenham) Ltd', 'MP Engineering (Chippenham) Ltd is a subcontract precision CNC machining company founded in the early 1970s, based in Chippenham, Wiltshire, specialising in high-temperature and exotic alloy machining for demanding applications. The company offers CNC milling and turning, prototype development, jigs and fixture manufacture, mechanical assembly, and in-house vapour blasting and ultrasonic cleaning. They work extensively with materials including Hastelloy, Titanium, Inconel, Monel, and Nitronic.', '{"company_type":"CNC Machining","website_url":"https://www.mp-engineering-uk.com","location":"Chippenham, Wiltshire, UK","certifications":null,"capabilities":["CNC Milling","CNC Turning","Prototype Development","Jig & Fixture Manufacture","Mechanical Assembly","Vapour Blasting","Ultrasonic Cleaning"],"industries":["General Engineering","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Hastelloy","Titanium","Inconel","Monel","Nitronic"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'R & A Engineering Ltd', 'R & A Engineering Ltd is a BS EN ISO 9001:2015 UKAS accredited subcontract CNC machining company based in Aylesbury, Buckinghamshire, operating from a 10,000 square foot facility. The company specialises in CNC milling (3, 4, and 5-axis up to one metre capacity), CNC turning (up to 10-inch billet), and sliding head turning, with CAD/CAM and multi-axis equipment. They have over 25 years of precision engineering experience serving customers across the UK Midlands and beyond.', '{"company_type":"CNC Machining","website_url":"https://randaeng.co.uk","location":"Aylesbury, Buckinghamshire, UK","certifications":["ISO 9001:2015"],"capabilities":["CNC Milling","CNC Turning","5-Axis Machining","Sliding Head Turning","Multi-Axis Machining"],"industries":["General Engineering","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wilbest Precision Engineering Limited', 'Wilbest Precision Engineering Limited is a subcontract precision CNC machining company established in 1965 and based in Huddersfield, West Yorkshire, holding ISO 9001 and ISO 14001 certifications with over 50 years in the industry. They specialise in CNC milling and turning, conventional machining, and complex 3D milled components across a wide range of materials including tool steels, Stellite, Inconel, and Hastelloy. The company provides quick-turnaround production and serves automotive and general manufacturing sectors.', '{"company_type":"CNC Machining","website_url":"https://wilbest.co.uk","location":"Huddersfield, West Yorkshire, UK","certifications":["ISO 9001","ISO 14001"],"capabilities":["CNC Milling","CNC Turning","Conventional Turning","Conventional Milling","3D Milling"],"industries":["Automotive","General Manufacturing"],"lead_time":null,"min_order":null,"employees":"10-49","established":1965,"materials":["Plastics","Ferrous Metals","Non-Ferrous Metals","Tool Steels","Stellite","Inconel","Hastelloy"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'B&B Precision Engineering', 'B&B Precision Engineering is an ISO 9001 accredited subcontract CNC machining company founded in 1998 and based in Clayton West, West Yorkshire, specialising in low to medium volume manufacture of complex, high-precision components requiring multiple process steps. The company offers CNC milling and turning, surface grinding, cylindrical grinding, internal grinding, hard part turning, and HVOF thermal spray coating including tungsten carbide and Stellite 6. They serve food processing machinery, commercial vehicles, classic vehicles, and specialist machinery sectors with worldwide delivery.', '{"company_type":"CNC Machining","website_url":"https://www.bandbprecision.co.uk","location":"Clayton West, West Yorkshire, UK","certifications":["ISO 9001"],"capabilities":["CNC Milling","CNC Turning","Surface Grinding","Cylindrical Grinding","Internal Grinding","Hard Part Turning","HVOF Thermal Spray Coating"],"industries":["Food Processing","Commercial Vehicles","Classic Vehicles","Specialist Machinery"],"lead_time":null,"min_order":null,"employees":"10-49","established":1998,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

