INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dunbeath Engineering Ltd', 'Dunbeath Engineering Ltd is a precision CNC machining company based in Dunbeath, Caithness, Scotland, specialising in CNC turning and milling with components up to 575mm diameter and overnight lights-out production capability. The company machines stainless steel, heat-treatable alloys, work-hardening materials, high-temperature alloys, aluminium, brass, and mild steel for oil and gas, automotive, aerospace, pharmaceutical, and defence sectors. They operate gantry robot loading equipment and multi-axis turning and milling centres.', '{"company_type":"CNC Machining","website_url":"https://dunbeathengineering.com","location":"Dunbeath, Caithness, Scotland, UK","certifications":null,"capabilities":["CNC Turning","CNC Milling","Multi-Axis Turning","Multi-Axis Milling","Grinding","Lights-Out Production"],"industries":["Oil & Gas","Automotive","Aerospace","Pharmaceutical","Defence","Rotating Equipment"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Stainless Steel","Heat-Treatable Alloys","Work-Hardening Materials","High-Temperature Alloys","Aluminium","Brass","Mild Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CNC Leicester Ltd', 'CNC Leicester Ltd is a BSi-certified precision engineering company based in Leicester, a member of the Midlands Aerospace Alliance, specialising in the machining of exotic materials for aerospace, petrochemical, motorsport, medical, marine, and rail sectors. The company operates CNC turning machines, 5-axis CNC milling centres, EDM, grinding, hot forging press, and wire EDM equipment, offering a comprehensive range of machining and specialist processes. They produce components requiring the most demanding tolerances and material properties.', '{"company_type":"CNC Machining","website_url":"https://www.cncleicester.com","location":"Leicester, Leicestershire, UK","certifications":["BSi Certified","Midlands Aerospace Alliance Member"],"capabilities":["CNC Turning","5-Axis CNC Milling","EDM","Wire EDM","Grinding","Hot Forging","Thread Milling","Chemical Blacking"],"industries":["Aerospace","Petrochemical","Motorsport","Medical","Marine","Rail"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Exotic Materials"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Millbrook Precision Engineering Limited', 'Millbrook Precision Engineering Limited is a medium-to-large subcontract CNC machining company based in Clay Cross, Chesterfield, Derbyshire, capable of machining components up to 10 tonnes with 3,000mm diameter or cube capacity. The company operates a mix of CNC and conventional manual machine tools performing boring, drilling, milling, and turning on metals including steel, aluminium, brass, and copper. They hold ISO 9001 certification and serve aerospace, automotive, medical, and energy sectors.', '{"company_type":"CNC Machining","website_url":"http://www.millbrookgroup.co.uk","location":"Clay Cross, Chesterfield, Derbyshire, UK","certifications":["ISO 9001"],"capabilities":["CNC Milling","CNC Turning","Horizontal Boring","Conventional Machining","Large Part Machining up to 10 Tonnes"],"industries":["Aerospace","Automotive","Medical","Energy"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Steel","Aluminium","Brass","Copper"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Madeley Precision Engineering Ltd', 'Madeley Precision Engineering Ltd is a specialist precision grinding and subcontract CNC machining company established in 1982 and based in Telford, Shropshire, operating from a 39,000 sq ft facility. The company offers CNC milling, CNC turning, surface grinding, cylindrical grinding, and centreless grinding, with CNC milling up to one cubic metre and CNC turning up to 900mm diameter. Their BS EN ISO 9001:2015 compliant quality system supports ultra-precision work to tolerances within 0.5 micron for spectrometer equipment OEMs.', '{"company_type":"CNC Machining","website_url":"http://www.madeleyprecision.com","location":"Telford, Shropshire, UK","certifications":["ISO 9001:2015"],"capabilities":["CNC Milling","CNC Turning","Surface Grinding","Cylindrical Grinding","Centreless Grinding","5-Axis CNC Machining"],"industries":["Scientific Instruments","General Engineering","Industrial"],"lead_time":null,"min_order":null,"employees":"50-99","established":1982,"materials":["Stainless Steel","Molybdenum","Special Metals"],"key_equipment":["5-Axis CNC Machining Centres (x3)","Horizontal CNC Machining Centres (x14)","CNC Lathes (x6)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');


