INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cwm Engineering Ltd', 'Cwm Engineering Ltd is a family-run sub-contract CNC precision machining company based in Cross Hands, South Wales, holding AS9100 Rev D, ISO 9001:2015, Cyber Essentials Plus and JOSCAR certification. The company has over 20 years of experience delivering high-precision CNC machining for aerospace, defence, medical and oil and gas sectors, offering 3, 4 and 5-axis CNC milling, CNC turning, full CMM inspection and laser marking with complete traceability.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.cwmengineering.co.uk","location":"Cross Hands, Carmarthenshire, Wales, UK","certifications":["AS9100 Rev D","ISO 9001:2015","Cyber Essentials Plus","JOSCAR"],"capabilities":["3-axis CNC Milling","4-axis CNC Milling","5-axis CNC Milling","CNC Turning","CMM Inspection","Laser Marking"],"industries":["Aerospace","Defense","Medical","Oil & Gas","Space"],"lead_time":null,"min_order":null,"employees":null,"established":2011,"materials":["Metals","Plastics"],"key_equipment":["CMM Inspection Equipment"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Castle Precision Engineering (Glasgow) Ltd', 'Castle Precision Engineering is a Glasgow-based manufacturer with over 70 years of history (founded 1951) specialising in high-precision critical gas turbine components for aerospace and energy industries. The company holds a 40-year supply relationship with Rolls-Royce and in 2024 was awarded an £85m multi-year contract for precision machined critical rotating aero engine parts. Castle is a high-quality turnkey supplier of complex machined components and assemblies, serving civil aerospace, defence, business aviation, space and medical sectors.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.castleprecision.com","location":"Glasgow, Scotland, UK","certifications":["AS9100","ISO 14001","SC21 Bronze"],"capabilities":["5-axis CNC Milling","CNC Turning","Multi-axis Machining","Complex Prismatic Parts","Turnkey Supply","Assembly"],"industries":["Aerospace","Defense","Energy","Space","Medical"],"lead_time":null,"min_order":null,"employees":"100-149","established":1951,"materials":["Titanium","Inconel","Aluminium Alloys","Superalloys"],"key_equipment":null,"data_source":"company_website + press_releases","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ASG Aerospace (ASG Group)', 'ASG Aerospace is a major UK aerospace manufacturing group headquartered in Stockport with sites across the North West, Yorkshire and the Midlands. The group operates more than 180 CNC machine tools across 9 approved site locations and employs nearly 500 people. ASG holds NADCAP accreditation for 8 chemical processing categories and 2 NDT categories, plus 31 individual customer approvals, and supplies detail parts and tooling to major OEMs including Airbus, BAE Systems and Rolls-Royce.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.asg-group.co","location":"Stockport, Greater Manchester, UK (multi-site: Coventry, Preston, Liverpool, Bromborough)","certifications":["AS9100","EN9100","ISO 9001","ISO 14001","NADCAP","SC21 Silver","SC21 Bronze","Cyber Essentials"],"capabilities":["CNC Machining","CNC Turning","Grinding","Assembly","Surface Treatment","Tooling for Composites","Metrology","Aircraft on Ground (AOG) Support"],"industries":["Aerospace","Defense","Nuclear"],"lead_time":null,"min_order":null,"employees":"450-499","established":2019,"materials":["Aluminium Alloys","Titanium","Nickel Alloys","Steel Alloys"],"key_equipment":["180+ CNC machine tools"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Supercraft Ltd', 'Supercraft is an established aerospace engineering business founded in 1982, operating a 48,000 sq ft facility in Byfleet, Surrey plus a site in Brough, East Yorkshire. The company holds NADCAP accreditation for non-destructive testing, chemical processing and heat treatment, and has major customer approvals from Airbus, BAE Systems, AgustaWestland, GKN Aerospace, Rolls-Royce, SAFRAN, GE Aviation and Thales. Supercraft specialises in precision machining, pipe bending, fabrication, surface treatment and assembly for the aerospace and defence sectors.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.supercraft.co.uk","location":"Byfleet, Surrey, UK (also Brough, East Yorkshire)","certifications":["NADCAP (NDT, Chemical Processing, Heat Treatment)","AS9100","BS EN AS9100"],"capabilities":["Precision Machining","Sheet Metal Fabrication","Pipe Bending","Welding","Brazing","Heat Treatment","Surface Treatment","Non-Destructive Testing","Assembly","Adhesive Bonding"],"industries":["Aerospace","Defense"],"lead_time":null,"min_order":null,"employees":"150-199","established":1982,"materials":null,"key_equipment":["Eaton Leonard Laservision Tube data center","CNC Pipe Benders"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Xcel Aerospace Limited', 'Xcel Aerospace is a UK aerospace manufacturer based in Romford, Essex with over 40 years of experience in delivering aerospace components. The company holds AS9100 and NADCAP accreditation for welding, and maintains strategic partnerships with UTC, Collins Aerospace and Rolls-Royce. Xcel''s capabilities span 5-axis CNC machining, water jet cutting, sheet metal fabrication and additive manufacturing, and it is a member of the ADS Group.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.xcelaerospace.com","location":"Romford, Essex, UK","certifications":["AS9100","NADCAP (Welding)","BSI Certified"],"capabilities":["5-axis CNC Machining","Multi-axis CNC Machining","Sliding Head Machining","Water Jet Cutting","Sheet Metal Fabrication","Metal Pressing and Forming","Assembly","Additive Manufacturing","Kitting"],"industries":["Aerospace","Defense"],"lead_time":"2-4 weeks (prototyping)","min_order":null,"employees":null,"established":null,"materials":["Aluminium Alloys"],"key_equipment":["5-axis CNC Machining Centres","Water Jet Cutting Systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
