INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Roscomac Ltd', 'Roscomac is a long-established CNC precision engineering company founded in 1976, based in Worthing, West Sussex. The company is certified to AS9100 Rev D and operates 24 hours a day, manufacturing aerospace safety-critical components including flight monitoring equipment and aircraft interior parts for commercial and military clients worldwide. Roscomac offers a vertically integrated value chain including 5-axis CNC machining, grinding and turning, with design-for-manufacture services and instant stock call-off options.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.roscomac.com","location":"Worthing, West Sussex, UK","certifications":["AS9100 Rev D","ISO 9001"],"capabilities":["5-axis CNC Milling","CNC Turning","CNC Grinding","Design for Manufacture","Assembly"],"industries":["Aerospace","Defense","Medical","Oil & Gas","Transport"],"lead_time":null,"min_order":null,"employees":null,"established":1976,"materials":null,"key_equipment":["Matsuura MAM72 (5-axis)","CNC Turning Centres","CNC Grinding Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Helix Precision Machining Ltd', 'Helix Precision Machining Ltd is a Hull-based precision engineering company established in 2003, specialising in CNC machining for aerospace, defence, medical, nuclear and renewable energy sectors. The company holds AS9100D certification and a direct BAE Systems approval, and offers CNC milling, turning, 5-axis machining, laser cutting and precision grinding. Helix operates an aerospace division out of its Global Business Park facility in Hull, East Yorkshire.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.helixprecision.co.uk","location":"Hull, East Yorkshire, UK","certifications":["AS9100D","BAE Systems Approved"],"capabilities":["CNC Milling","CNC Turning","5-axis Milling","Laser Cutting","Precision Surface Grinding","CAD Design"],"industries":["Aerospace","Defense","Automotive","Medical","Nuclear","Oil & Gas","Renewable Energy"],"lead_time":null,"min_order":null,"employees":null,"established":2003,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

