INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Tarvin Precision Ltd', 'Tarvin Precision Ltd is a sub-contract precision CNC manufacturing and assembly company based at Hawarden Business Park in Flintshire, North Wales. The company draws on over three decades of experience and is certified to AS9100 Rev D and Cyber Essentials Plus for defence work. Tarvin specialises in low-volume, high-variety aerospace and defence CNC machining with full traceability, offering multi-axis machining, fine grinding, metrology and assembly from design support through to finished component. The company is listed on the OASIS aerospace supplier database.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://tarvinprecision.co.uk","location":"Hawarden, Flintshire, Wales, UK","certifications":["AS9100 Rev D","ISO 9001","Cyber Essentials Plus","JOSCAR"],"capabilities":["Multi-axis CNC Machining","CNC Milling","CNC Turning","Fine Grinding","Metrology","Assembly","CAD/CAM Design Support"],"industries":["Aerospace","Defense","Scientific Research"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CNF Precision Engineering Ltd', 'CNF Precision Engineering Ltd is a long-established Aylesbury, Buckinghamshire precision machining company founded in 1967, certified to AS/EN9100 Rev D and JOSCAR registered. The company describes itself as one of the leading precision machining specialists for aerospace and defence, and is listed on the OASIS database (reference 6113744888). CNF offers multi-axis CNC milling, CNC turning, sliding head and horizontal CNC machining, serving aerospace, defence, medical, scientific and electronics industries.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.cnfengineering.com","location":"Aylesbury, Buckinghamshire, UK","certifications":["AS9100 Rev D","ISO 9001:2015","JOSCAR"],"capabilities":["Multi-axis CNC Machining","CNC Milling (3, 4, 5-axis)","CNC Turning","Sliding Head Machining","Horizontal CNC Machining","Design Services","Inspection"],"industries":["Aerospace","Defense","Medical","Electronics","Scientific"],"lead_time":null,"min_order":null,"employees":null,"established":1967,"materials":null,"key_equipment":["Multi-pallet CNC Milling Systems","Sliding Head Machines","Multi-axis Turn/Mill"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HEC Precision Ltd', 'HEC Precision (Heston Engineering Company) is a Southall, Middlesex precision engineering company that has operated near London Heathrow since the early 1970s and was an early adopter of 5-axis CNC technology in 1998. The company holds EN 9100 and ISO 9001 certifications plus direct Airbus and BAE Systems approvals, and operates a 10,000 sq ft facility with class-leading automation including unmanned production capability. HEC Precision serves aerospace and advanced manufacturing sectors with complex precision machined components.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.hec-precision.co.uk","location":"Southall, Middlesex, UK","certifications":["EN 9100","ISO 9001","Airbus Approved","BAE Systems Approved"],"capabilities":["5-axis CNC Machining","CNC Milling","CNC Turning","Finishing Services","Unmanned Production"],"industries":["Aerospace","Advanced Manufacturing"],"lead_time":null,"min_order":null,"employees":null,"established":1970,"materials":null,"key_equipment":["5-axis CNC Machining Centres"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Atlantic Precision Engineering Ltd', 'Atlantic Precision Engineering is a Hampshire-based aerospace CNC machining company located at Blackbushe Business Park, Yateley, certified to AS9100 and JOSCAR registered. The company specialises in Matsuura 5-axis palletised CNC machining and operates a dedicated plastics and composites machining cell, serving aerospace, motorsport and medical markets. Atlantic Precision was acquired by FMT Aerospace in 2023 and continues to operate under the Atlantic Precision brand.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.atlantic-precision.co.uk","location":"Yateley, Hampshire, UK","certifications":["AS9100","ISO 9001","Cyber Essentials","JOSCAR"],"capabilities":["5-axis Palletised CNC Machining","High-Speed CNC Milling","CNC Turning","Plastics and Composites Machining","Mechanical Assembly"],"industries":["Aerospace","Motorsport","Medical","OEM"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":null,"key_equipment":["Matsuura 5-axis Palletised CNC","Mazak INTEGREX J200","Mazak CNC Mills and Turners","Hurco High-Speed CNC"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Timpson Engineering Ltd', 'Timpson Engineering is an Oxfordshire-based CNC machining company certified to AS9100 and holding JOSCAR registration, backed by over 45 years of precision engineering experience. Based in Stanford in the Vale, Oxfordshire, the company is an approved ADS Group member and serves aerospace, defence, motorsport and hi-tech sectors. Timpson Engineering holds Cyber Essentials Plus accreditation in addition to its aerospace quality certifications.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.timpsonengineering.co.uk","location":"Stanford in the Vale, Oxfordshire, UK","certifications":["AS9100 Rev D","ISO 9001","Cyber Essentials Plus","JOSCAR"],"capabilities":["CNC Machining","Precision Engineering"],"industries":["Aerospace","Defense","Motorsport"],"lead_time":null,"min_order":null,"employees":null,"established":2021,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rotec Engineering Ltd', 'Rotec Engineering is a precision CNC machining company based in Evesham, Worcestershire, certified to AS9100 Rev D and ISO 9001:2015. The company has invested £8 million in its Advanced Manufacturing Centre and operates an automated 24-hour facility using sliding head, 3-axis, 4-axis and 5-axis machining technology. Rotec serves aerospace, oil and gas, automotive (including Formula 1) and industrial sectors from its Vale Business Park facility.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.rotec-ltd.com","location":"Evesham, Worcestershire, UK","certifications":["AS9100 Rev D","ISO 9001:2015"],"capabilities":["Sliding Head CNC Machining","3-axis CNC Machining","4-axis CNC Machining","5-axis CNC Machining","Automated 24-hour Production"],"industries":["Aerospace","Oil & Gas","Automotive","Motorsport","Industrial"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":null,"key_equipment":["Sliding Head CNC Machines","5-axis CNC Machining Centres"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'TML Precision Engineering Ltd', 'TML Precision Engineering is a Norfolk-based precision CNC machining company with approximately 30 years of operational history, certified to EN 9100:2018 (AS9100D) and ISO 9001:2015 by BSI. TML operates over 25 CNC machines at its Hethel facility near Norwich and was the first company in Norfolk to achieve multi-pallet unmanned 5-axis machining capability. The company serves aerospace, defence, security, medical, motorsport and renewable energy sectors, machining aluminium, steel, titanium, PTFE and exotic stainless steels.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.tml.co.uk","location":"Hethel, Norfolk, UK","certifications":["AS9100D","EN 9100:2018","ISO 9001:2015"],"capabilities":["3-axis CNC Machining","5-axis CNC Machining","CNC Turning","Mill-Turning","CNC Spark Erosion (EDM)","Wire EDM","Finishing & Assembly","CMM Inspection"],"industries":["Aerospace","Defense","Security","Medical","Motorsport","Renewable Energy","Technology"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Aluminium","Steel","Titanium","PTFE","Acetal","Exotic Stainless Steels","Plastics"],"key_equipment":["25+ CNC Machines (multi-pallet unmanned 5-axis)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'M-CNC Precision Engineering Ltd', 'M-CNC is a Somerset-based precision engineering company certified to AS9100 Rev D, ISO 9001, ISO 14001, JOSCAR and Cyber Essentials Plus, serving aerospace primes including Rolls-Royce, Safran, Leonardo and Babcock. Founded in 2011 and based near Bridgwater, M-CNC offers 3, 5 and 9-axis CNC milling, mill-turning, CNC turning and 5-axis wire EDM, with SolidWorks, HyperMill and EDGECAM programming capability. The company specialises in titanium and aerospace alloy machining.', '{"company_type":"CNC Machining (Aerospace)","website_url":"https://www.m-cnc.co.uk","location":"Bridgwater, Somerset, UK","certifications":["AS9100 Rev D","ISO 9001","ISO 14001","JOSCAR","RISQS","Cyber Essentials Plus"],"capabilities":["3-axis CNC Milling","5-axis CNC Milling","9-axis CNC Milling","CNC Turning","CNC Mill-Turn","5-axis Wire EDM","CMM Measurement","CAD-CAM Programming"],"industries":["Aerospace","Defense","Marine","Military","Agricultural"],"lead_time":null,"min_order":null,"employees":null,"established":2011,"materials":["Titanium","Aerospace Alloys"],"key_equipment":["5-axis Wire EDM","Aberlink CMM Systems","Bar-Fed CNC Turning Centres"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

