VALUES ('Products', 'Manufacturer', 'SevenHills Fabrication Limited', 'SevenHills Fabrication is a sub-contract fabrication and laser cutting specialist based in Sheffield with origins dating back to 1926 as J A Wilkinson & Co. Certified to BS EN ISO 9001:2015 and EN 1090, the company offers flat and tube laser cutting, CNC bending, tube manipulation, powder coating, and assembly. They serve aerospace, agriculture, automotive, defence, oil and gas, and construction sectors with a team of nearly 50 staff.', '{"company_type":"Sheet Metal Fabrication","website_url":"https://sevenhillsfabrication.com","location":"Holbrook Industrial Estate, Sheffield, South Yorkshire, UK","certifications":["BS EN ISO 9001:2015","EN 1090 Execution Class 2","UKCA Accreditation"],"capabilities":["Flat Bed Laser Cutting","Tube Laser Cutting","CNC Bending","Tube Manipulation","Sheet Metalwork","Powder Coating","Assembly","Design & Consultancy"],"industries":["Aerospace","Agriculture","Automotive","Construction","Defence","Oil & Gas","Materials Handling","Warehouse Solutions"],"lead_time":null,"min_order":null,"employees":"20-49","established":1926,"materials":["Steel","Aluminium","Stainless Steel"],"key_equipment":["Bystronic ByTube Star 130 tube laser (installed 2024)","CNC bending equipment","Flatbed laser cutting systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

