INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Yorkshire Profiles Ltd', 'Yorkshire Profiles is a family-run UK laser cutting and metal fabrication manufacturer established in 2001, operating CNC laser cutting machines 24/7. ISO 9001 registered, the company replaced its CO2 lasers in 2020 with third-generation fibre lasers featuring locus beam control technology. They maintain full material traceability to BS EN 10204 3.1 and deburr all parts as standard.', '{"company_type":"Sheet Metal Fabrication","website_url":"https://www.yorkshireprofiles.co.uk","location":"Yorkshire, UK","certifications":["ISO 9001"],"capabilities":["Laser Cutting","Metal Fabrication","Deburring"],"industries":["General Industrial","Engineering","Construction"],"lead_time":null,"min_order":null,"employees":null,"established":2001,"materials":["Aluminium","Steel","Stainless Steel","Hardened Steel"],"key_equipment":["3rd generation fibre lasers with locus beam control"],"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

