INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pentagon Plastics Ltd', 'Pentagon Plastics Group (trading since 1972, operating as Pentagon since 1979) is a UK injection moulding and toolmaking company based in Horsham, West Sussex. They operate 12 injection moulding machines ranging from 22 to 280 tonnes, handling shot weights from 0.5 to 500 grams. The company provides mould tool design and manufacture alongside production moulding, laser welding, and CMM inspection.', '{"company_type":"Injection Molding","website_url":"https://www.pentagonplastics.co.uk","location":"Horsham, West Sussex, UK","certifications":["ISO 9001:2015","Made in Britain","BPF Member","GTMA Member"],"capabilities":["Injection Molding","Tool Making","Laser Welding","CMM Inspection","Design for Manufacture"],"industries":["Medical","Aerospace","Electrical","Construction","Security","Marine","Defence"],"lead_time":null,"min_order":null,"employees":null,"established":1972,"materials":["LDPE","HDPE","PEEK","TPE","Nylon (PA)"],"key_equipment":"12 injection moulding machines, 22T–280T; EDM, CNC tooling; CMM inspection","data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Polymermedics Ltd', 'Polymermedics is a Cornwall-based technical injection moulding specialist with 45 years of experience, operating 35 injection moulding machines from 5 to 350 tonnes on a 24/7 basis. The company produces approximately 2 billion parts annually and is CE Mark capable for Class I sterile medical devices. Capabilities include micro-moulding, optical precision manufacturing, validation, metrology, and assembly.', '{"company_type":"Injection Molding","website_url":"https://polymermedics.com","location":"St Austell, Cornwall, UK","certifications":["CE Mark capability (Class I sterile medical devices)"],"capabilities":["Injection Molding","Micro-Moulding","Optical Precision Moulding","Validation","Metrology","Assembly"],"industries":["Medical","Defence"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Bioplastics (corn starch)","Standard Thermoplastics"],"key_equipment":"35 injection moulding machines, 5T–350T; 2 billion parts/year capacity","data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rosti McKechnie Ltd', 'Rosti UK (formerly Derwent Plastics, est. 1934) is a high-precision injection moulding and contract manufacturing site located in Stamford Bridge, York. The facility covers 8,000 m² and operates presses starting from 50 tonnes, offering cleanroom moulding, multi-shot moulding, laser etching, ultrasonic welding, printing, and assembly. The site holds ISO 9001, ISO 13485, and ISO 50001 certifications.', '{"company_type":"Injection Molding","website_url":"https://www.rosti.com/en-us/locations/rosti-uk/","location":"Stamford Bridge, York, North Yorkshire, UK","certifications":["ISO 9001","ISO 13485","ISO 50001"],"capabilities":["Injection Molding","Multi-Shot Moulding","Cleanroom Moulding","Laser Etching","Ultrasonic Welding","Assembly"],"industries":["Medical","Water Filtration","Packaging","Automotive"],"lead_time":null,"min_order":null,"employees":null,"established":1934,"materials":null,"key_equipment":"Injection moulding presses from 50T; 8,000 m² facility","data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

