VALUES ('Products', 'Manufacturer', 'Dickinson Philips Ltd', 'Dickinson Philips is a Yorkshire injection moulding and toolmaking company established in 1979, based in Skipton. They offer new tooling design, existing tooling support, laser cutting and engraving, and a 90-minute prototype service. The company operates Swiss, Japanese, and Italian injection moulding machinery and serves the wider Yorkshire and North West regions.', '{"company_type":"Injection Molding","website_url":"https://dickinsonphilips.com","location":"Skipton, North Yorkshire, UK","certifications":null,"capabilities":["Injection Molding","Tool Making","Laser Cutting","Laser Engraving","Rapid Prototyping"],"industries":["General Manufacturing"],"lead_time":null,"min_order":null,"employees":null,"established":1979,"materials":null,"key_equipment":"Swiss, Japanese, and Italian injection moulding machines; 90-minute prototype service","data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
