INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Butser Rubber Ltd', 'Butser Rubber is a Hampshire-based custom rubber moulding specialist offering injection, compression, and transfer moulding in a wide range of elastomers. They hold JOSCAR and AS9102 certifications alongside ISO 9001 and ISO 14001, and serve aerospace, automotive, motorsport, and agricultural industries. The company also offers laser cutting, water jet cutting, and Kanban scheduling for regular call-offs.', '{"company_type":"Rubber Molding","website_url":"https://www.butserrubber.com","location":"Liss, Hampshire, UK","certifications":["ISO 9001","ISO 14001","JOSCAR","AS9102","PPAP Level 3"],"capabilities":["Rubber Injection Molding","Compression Molding","Transfer Molding","Laser Cutting","Water Jet Cutting","Gasket Manufacturing"],"industries":["Aerospace","Automotive","Motorsport","Agricultural"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["EPDM","Nitrile","Viton (FKM)","Silicone","Neoprene","Natural Rubber","HNBR"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Martin''s Rubber Company Ltd', 'Martin''s Rubber Company is one of the UK''s oldest rubber engineering businesses, established in 1865 and based in Southampton. They design, develop, and manufacture over 100 custom rubber compounds including proprietary formulations (Envirolast, FRlite), and offer rubber-to-metal and rubber-to-plastic bonding, Finite Element Analysis, and cleanroom capabilities. They serve aerospace, defence, oil and gas, nuclear, motorsport, and prestige automotive markets.', '{"company_type":"Rubber Molding","website_url":"https://www.martins-rubber.co.uk","location":"Southampton, Hampshire, UK","certifications":["ISO 9001 (BSI)","Cyber Essentials Plus"],"capabilities":["Rubber Moulding","Rubber-to-Metal Bonding","Rubber-to-Plastic Bonding","Compound Design","FEA Simulation","Cleanroom Manufacturing"],"industries":["Aerospace","Defence","Oil and Gas","Nuclear","Motorsport","Prestige Automotive","Processing"],"lead_time":null,"min_order":null,"employees":null,"established":1865,"materials":["100+ proprietary rubber compounds","Envirolast","FRlite"],"key_equipment":"Multiple axis machining centres; cleanroom; compound testing laboratory","data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SRM Industries Ltd', 'SRM Industries is a Derbyshire-based custom rubber moulding company with over 40 years of experience, specialising in injection and compression rubber moulding. They recently invested in 11 new Maplan injection moulding machines and 2 Mewo cryogenic de-flashing machines. JOSCAR-registered, they serve electronics, rail, petrochemical, nuclear, medical, defence, and marine sectors.', '{"company_type":"Rubber Molding","website_url":"https://srm-industries.com","location":"Hatton, Derbyshire, UK","certifications":["ISO 9001","JOSCAR"],"capabilities":["Rubber Injection Molding","Compression Molding","Rubber-to-Metal Bonding","Rubber-to-Plastic Bonding","Cryogenic De-Flashing","CNC Milling","Die Cutting","Gasket Manufacturing"],"industries":["Electronics","Rail","Petrochemical","Construction","Medical","Defence","Nuclear","Marine"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Natural Rubber","Silicone","Neoprene","Nitrile","EPDM","Viton (FKM)"],"key_equipment":"11 Maplan injection moulding machines; 2 Mewo cryogenic de-flashing machines","data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'TRP Polymer Solutions Ltd', 'TRP Polymer Solutions is a Hereford-based custom rubber moulding company established in 2004, specialising in high-performance elastomers including FFKM and FKM for extreme-environment applications. They design and manufacture custom O-rings, seals, gaskets, diaphragms, and precision ground rollers for nuclear, aerospace, oil and gas, pharmaceutical, and hydrogen electrolyser applications. The company holds triple ISO accreditation.', '{"company_type":"Rubber Molding","website_url":"https://trp.co.uk","location":"Hereford, Herefordshire, UK","certifications":["ISO 9001:2015","ISO 14001:2015","ISO 45001:2018"],"capabilities":["Custom Rubber Moulding","O-Ring Manufacturing","Seal Manufacturing","Gasket Manufacturing","Diaphragm Manufacturing"],"industries":["Nuclear","Aerospace","Oil and Gas","Pharmaceutical","Food","Chemical Processing","Green Energy"],"lead_time":null,"min_order":null,"employees":null,"established":2004,"materials":["FFKM","FKM (Viton)","Silicone","HNBR"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'DP Seals Ltd', 'DP Seals is a Poole, Dorset specialist in custom rubber seals, gaskets, and mouldings with over 40 years of manufacturing experience. They operate more than 30 presses and an in-house CNC toolroom with CAD/CAM capabilities, serving aerospace, defence, energy, medical, motorsport, and subsea markets. The company holds AS 9100 aerospace quality certification alongside ISO 9001, ISO 14001, and ISO 45001.', '{"company_type":"Rubber Molding","website_url":"https://dpseals.com","location":"Poole, Dorset, UK","certifications":["AS 9100","ISO 9001","ISO 14001","ISO 45001","Cyber Essentials"],"capabilities":["Rubber Moulding","Rubber-to-Metal Bonding","Micro Moulding","Fluorination","CNC Toolmaking","Cryogenic Cleaning"],"industries":["Aerospace","Defence","Oil and Gas","Renewables","Medical","Motorsport","Subsea"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["FFKM","VITON Extreme","FKM","Silicone","EPDM","Nitrile"],"key_equipment":"30+ presses; in-house CNC toolroom; cryogenic cleaning at -130°C","data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
