VALUES ('Products', 'Manufacturer', 'Lestercast Ltd', 'A Leicester-based investment casting foundry with over 50 years of experience producing more than 1 million parts annually for 170 global customers across a wide range of alloys. Holds an unusually broad set of accreditations including IATF 16949 for automotive, Fit4Nuclear, and JOSCAR for defence and aerospace supply chains. Capabilities span lost-wax casting, rapid prototyping with 3D-printed wax patterns, toolmaking, CNC machining, and CMM inspection.', '{"company_type":"Investment Casting","website_url":"https://lestercast.co.uk/","location":"Leicester, Leicestershire, UK","certifications":["ISO 9001:2015","IATF 16949","JOSCAR","Fit4Nuclear","Cyber Essentials"],"capabilities":["Investment Casting","Lost Wax Casting","Rapid Prototyping","Toolmaking","CNC Machining","CMM Inspection","Surface Treatments","Component Reverse Engineering"],"industries":["Automotive","Motorsport","Rail","Nuclear","Hydrogen","Oil & Gas","Marine","Medical","Defence"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Carbon Steel","Stainless Steel","Aluminium","Nickel Superalloys","Cobalt Superalloys","Brass","Bronze","Zinc Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aeromet International Ltd', 'A leading UK supplier of aluminium and magnesium sand castings and investment castings for the aerospace and defence industries, operating three sites in the UK and now part of Pursuit Aerospace. Specialises in fully-finished, assembly-ready cast parts and has developed its proprietary SOPHIA high-property investment casting process for demanding structural applications. Serves primarily aerospace and defence prime contractors and Tier 1 suppliers.', '{"company_type":"Investment Casting","website_url":"https://www.aeromet.co.uk/","location":"Worcester, Worcestershire, UK","certifications":null,"capabilities":["Aluminium Sand Casting","Magnesium Sand Casting","Aluminium Investment Casting","SOPHIA High-Property Investment Casting","Rapid Prototyping","Assembly-Ready Components"],"industries":["Aerospace","Defence"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["Aluminium Alloys","Magnesium Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'W.H. Tildesley Ltd', 'One of the oldest surviving drop forging companies in the United Kingdom, operating since approximately 1881 from Willenhall in the West Midlands Black Country. Specialises in closed-die (impression die) drop forging across a very wide range of materials including superalloys, titanium, and aluminium, producing forgings from 25 grams to 100 kg. Serves over 20 industry sectors including aerospace, nuclear, oil and gas, defence, and rail.', '{"company_type":"Closed-Die Forging","website_url":"https://www.whtildesley.com/","location":"Willenhall, West Midlands, UK","certifications":["ISO 9001"],"capabilities":["Closed-Die Drop Forging","Open-Die Forging","CNC Machining","Heat Treatment","Surface Finishing","Forging Simulation","Die Manufacture"],"industries":["Aerospace","Nuclear","Oil & Gas","Defence","Naval & Marine","Rail","Automotive","Pharmaceutical","Power Generation"],"lead_time":null,"min_order":null,"employees":"50-99","established":1881,"materials":["Carbon Steel","Alloy Steel","Stainless Steel","Duplex Steel","Superalloys","Aluminium Alloys","Nickel Alloys","Brass","Bronze","Silicon Bronze"],"key_equipment":["9 Power Hammers (350kg to 6.3 tonne)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Brooks Forgings Ltd', 'A West Midlands forging and fabrication specialist founded in 1960, operating 26 distinct manufacturing processes including drop forging, upset forging, open-die forging, ring rolling, flash butt welding, robot welding, and casting from their Cradley Heath site. Supplies forged and fabricated components to civil engineering, defence, offshore, petrochemical, rail, and power generation sectors. Holds ISO 9001, ISO 14001, and ISO 45001 certifications.', '{"company_type":"Closed-Die Forging","website_url":"https://brooksforgings.co.uk/","location":"Cradley Heath, West Midlands, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","CE EN1090","CE EN15048"],"capabilities":["Drop Forging","Upset Forging","Open-Die Forging","Ring Rolling","Flash Butt Welding","Robot Welding","Fabrication","CNC Machining","CAD/CAM Design"],"industries":["Civil Engineering","Defence","Offshore","Petrochemical","Rail","Power Generation","Naval & Marine","Mining"],"lead_time":null,"min_order":null,"employees":"50-99","established":1960,"materials":["Steel","Aluminium","Brass","Bronze","Alloy Steels"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Somers Forge Ltd', 'A world-leading open-die forge master based in Halesowen in the West Midlands Black Country, with heritage tracing back to 1697 and the modern company established in 1866. Manufactures forgings from 1 kg to over 80 tonnes and up to 23 metres in length, serving defence, marine, nuclear, oil and gas, aerospace, and power generation markets. Holds AS9100 Rev D and ISO 9001:2015 certifications and operates an in-house test laboratory.', '{"company_type":"Open-Die Forging","website_url":"https://www.somersforge.com/","location":"Halesowen, West Midlands, UK","certifications":["AS9100 Rev D","BS EN 9100:2015","ISO 9001:2015"],"capabilities":["Open-Die Forging","Heat Treatment","CNC Machining","Turning","Boring","5-Axis Milling","Test Laboratory","Steel Stockholding"],"industries":["Defence","Marine","Nuclear","Oil & Gas","Aerospace","Rail","Mining","Power Generation"],"lead_time":null,"min_order":null,"employees":"100-249","established":1866,"materials":["Steel Alloys"],"key_equipment":["Range of Forging Presses and Hammers (1kg to 80+ tonne capacity)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sheffield Forgemasters Ltd', 'A world-renowned Sheffield forge and foundry celebrating its 250th anniversary in 2026, capable of producing the largest and most technically challenging cast and forged steel components in the world, including hollow, solid, and near-net shaped forgings up to 300 tonnes. Now government-owned and investing £138 million in a new large open-die forging facility to support UK defence and civil nuclear programmes. Specialises in nuclear-grade steel, defence, and offshore structures.', '{"company_type":"Open-Die Forging","website_url":"https://www.sheffieldforgemasters.com/","location":"Sheffield, South Yorkshire, UK","certifications":null,"capabilities":["Open-Die Forging","Steel Casting","CNC Machining","Heat Treatment","NDT","Electron Beam Welding","Melt Shop","Foundry"],"industries":["Defence & Marine","Civil Nuclear","Offshore Oil & Gas","Renewables","Power Generation"],"lead_time":null,"min_order":null,"employees":"500+","established":1776,"materials":["Nuclear-Grade Steel","High-Alloy Steels"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Independent Forgings and Alloys Ltd', 'A privately owned Sheffield forge uniquely capable of open-die radial forging, press forging, hammer forging, ring rolling, closed-die extrusion, drop stamp, and blade forging all on a single site — the only such facility in the world. Holds customer approvals from Airbus, Boeing, Rolls-Royce, Safran, GE Aerospace, and Honeywell, and is certified to AS9100 Rev D. Serves aerospace, oil and gas, civil nuclear, and power generation markets in nickel, titanium, cobalt, and steel alloys.', '{"company_type":"Open-Die Forging","website_url":"https://independentforgings.com/","location":"Sheffield, South Yorkshire, UK","certifications":["AS9100 Rev D","ISO 9001:2015","ISO 45001","ISO 14001","ISO/IEC 17025:2017"],"capabilities":["Open-Die Radial Forging","Press Forging","Hammer Forging","Ring Rolling","Closed-Die Extrusion","Drop Stamp Forging","Blade Forging","Heat Treatment","CNC Machining"],"industries":["Aerospace","Oil & Gas","Civil Nuclear","Power Generation","Off-Highway","Motorsport"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["Nickel Alloys","Titanium Alloys","Cobalt Alloys","Stainless Steel","Aluminium Alloys","Special Steel Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Forged Solutions Group', 'A multi-site UK forging group with over 100 years of heritage and facilities in Derbyshire, Sheffield, and South Wales (Blaenavon), specialising in open-die forgings, seamless rolled rings, closed-die forgings, and extrusions for the aerospace, defence, and space sectors. Manufactures shafts, rings, discs, asymmetric forgings, and blades in titanium, nickel, aluminium, copper, and steel alloys. Operates a world-class in-house materials testing and certification laboratory.', '{"company_type":"Open-Die Forging","website_url":"https://www.forgedsolutionsgroup.com/","location":"Matlock, Derbyshire, UK","certifications":null,"capabilities":["Open-Die Forging","Closed-Die Forging","Seamless Ring Rolling","Extrusions","Heat Treatment","CNC Machining","Materials Testing & Certification"],"industries":["Aerospace","Defence","Space","Energy","Mining","Oil & Gas"],"lead_time":null,"min_order":null,"employees":"250-499","established":null,"materials":["Titanium Alloys","Nickel Alloys","Aluminium Alloys","Copper Alloys","Steel Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
