INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Midland Pressure Diecasting Ltd', 'A West Midlands high-pressure die casting specialist producing aluminium and zinc alloy components with integrated CNC machining, finishing, coating, and assembly services from a single site. Holds ISO 9001:2015 certification and positions itself as a one-stop supply chain solution for design-to-delivery casting projects. Serves a broad range of industrial sectors requiring precision non-ferrous pressure castings.', '{"company_type":"Die Casting","website_url":"https://midlandpressurediecasting.co.uk/","location":"West Midlands, UK","certifications":["ISO 9001:2015"],"capabilities":["High-Pressure Die Casting","CNC Machining","Tool Design & Manufacture","Surface Finishing","Coating","Assembly"],"industries":["General Engineering","Automotive","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Aluminium Alloys","Zinc Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'MRT Castings Ltd', 'A Hampshire-based family-owned die casting company founded in 1947, operating one of the most modern aluminium high-pressure die casting foundries in the UK with fully automated production cells featuring real-time shot control. Certified to ISO 9001:2015, ISO 14001:2015, and ISO 45001:2018, and holds the Queen''s Award for Enterprise. Serves aerospace, defence, medical, electronics, automotive, and marine sectors.', '{"company_type":"Die Casting","website_url":"https://www.mrt-castings.co.uk/","location":"Andover, Hampshire, UK","certifications":["ISO 9001:2015","ISO 14001:2015","ISO 45001:2018","Cyber Essentials Plus"],"capabilities":["High-Pressure Die Casting","Gravity Die Casting","CNC Machining","Toolmaking","Surface Finishing","Assembly"],"industries":["Aerospace","Defence","Medical","Electronics","Automotive","Marine","Rail","Audio"],"lead_time":null,"min_order":null,"employees":"100-249","established":1947,"materials":["Aluminium Alloys","Zinc Alloys","Copper Alloys"],"key_equipment":["Fully Automated HPDC Production Cells with Real-Time Shot Control"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'McDonald Diecasting Ltd', 'A West Midlands zinc die casting specialist with over 80 years of experience producing precision-finished zinc pressure die castings at its factory on the Coneygre Industrial Estate, Tipton. Holds ISO 9001 accreditation and specialises in aesthetically finished components for consumer-facing industries including medical devices, home fixtures, leisure and gaming, and automotive. Offers a full suite of finishing options including chrome plating, powder coating, and polishing.', '{"company_type":"Die Casting","website_url":"https://www.mcdonald-diecasting.co.uk/","location":"Tipton, West Midlands, UK","certifications":["ISO 9001"],"capabilities":["High-Pressure Zinc Die Casting","Prototyping","Chrome Plating","Powder Coating","Polishing","Assembly"],"industries":["Medical Devices","Automotive","Home & Bathroom","Leisure & Gaming","Agricultural","Electrical & Electronics"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Zinc Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kemlows Diecasting Products Ltd', 'A Hertfordshire-based high-pressure die casting foundry specialising in aluminium and zinc alloys for automotive, electronics, medical, and white goods sectors, holding both ISO 9001:2015 and IATF 16949:2016 automotive certifications. Offers CAD design and flow simulation, CNC machining, tooling services, and full assembly. Is a member of The Diecasting Society, Make UK, and the Cast Metals Federation.', '{"company_type":"Die Casting","website_url":"https://kemlows.co.uk/","location":"Hoddesdon, Hertfordshire, UK","certifications":["BS EN ISO 9001:2015","IATF 16949:2016"],"capabilities":["High-Pressure Aluminium Die Casting","High-Pressure Zinc Die Casting","CAD Design","Flow Simulation","CNC Machining","Tooling","Finishing","Assembly"],"industries":["Automotive","Telecommunications","White Goods","Medical","Electronics","Marine","Garden Equipment"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Aluminium Alloys (LM2, LM6, LM20, LM24)","Zinc Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Newby Foundries Group', 'A Wednesbury-based foundry group established circa 1890, operating 25,000 m² across four West Midlands sites with 240 staff producing 4,500 tonnes of castings annually in iron, steel, aluminium, and zinc. Offers an exceptionally wide range of processes including shell moulding, airset moulding, cold box core blowing, 3D sand printing, gravity die casting, and investment casting. Holds IATF 16949 and ISO 9001 certifications and serves automotive, EV, hydraulic, marine, rail, and defence markets.', '{"company_type":"Shell Mold Casting","website_url":"https://www.newbyfoundries.co.uk/","location":"Wednesbury, West Midlands, UK","certifications":["IATF 16949","ISO 9001"],"capabilities":["Shell Moulding","Airset Moulding","Cold Box Core Blowing","3D Sand Printing","Gravity Die Casting","Investment Casting (Lost Wax)","Aluminium Casting","Zinc Casting","Steel Casting"],"industries":["Automotive","Electric Vehicles","Hydraulic Systems","Pumps","Marine","Oil & Gas","Rail","Defence","Construction"],"lead_time":null,"min_order":null,"employees":"100-249","established":1890,"materials":["Iron","Steel","Aluminium","Zinc"],"key_equipment":["4 Polygram Shell Moulding Machines (8 stations)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wrekin Shell Mouldings Ltd', 'A Telford, Shropshire foundry established in 1979 and certified to ISO 9001:2015, specialising in the highly precise shell moulding process for complex bronze and phosphor bronze castings. Supplies finished components via integrated CNC precision machining to the railways, marine, water and fire-fittings, automotive, pneumatics, valve, and construction industries. Focuses on LG2, LG4, phosphor bronze, and G3 alloys.', '{"company_type":"Shell Mold Casting","website_url":"https://www.wrekin-shell-mouldings.co.uk/","location":"Telford, Shropshire, UK","certifications":["ISO 9001:2015"],"capabilities":["Shell Mould Casting","CNC Precision Machining"],"industries":["Railways","Marine","Water & Fire Fittings","Fire Protection","Automotive","Pneumatics","Valve Manufacturing","Construction"],"lead_time":null,"min_order":null,"employees":"10-49","established":1979,"materials":["Bronze LG2 (CC491K)","Bronze LG4 (CC492K)","Phosphor Bronze PB2","G3 Bronze"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'NovaCast Ltd', 'A Wiltshire-based multi-process casting foundry certified to ISO 9001:2015 and ISO 14001:2025, offering one of the widest ranges of casting processes in the UK including sand casting, shell mould casting, investment casting, gravity die casting, lost foam casting, and silica sol casting. Serves oil and gas, transport, energy, defence, and architectural metalwork sectors with ferrous, aluminium, bronze, stainless steel, and cast iron alloys. Holds an EcoVadis Silver Medal for sustainability.', '{"company_type":"Sand Casting","website_url":"https://www.novacast.co.uk/","location":"Melksham, Wiltshire, UK","certifications":["ISO 9001:2015","ISO 14001:2025","EcoVadis Silver Medal"],"capabilities":["Sand Casting","Shell Mould Casting","Investment Casting","Gravity Die Casting","Lost Foam Casting","Silica Sol Casting","CNC Machining","Pattern & Toolmaking","Rapid Prototyping","Fabrication"],"industries":["Oil & Gas","Transport","Energy","Defence","Architectural Metalwork","Pumps & Valves","General Engineering"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Aluminium Alloys","Bronze","Gunmetal","Phosphor Bronze","Stainless Steel","Carbon Steel","Grey Cast Iron","SG Cast Iron","Austempered Ductile Iron"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Finecast Foundry Ltd', 'A West Sussex sand casting foundry established in 2002, operating an 84-person team across a 5,560 m² site in Littlehampton and known as one of the UK''s leading manufacturers of high-integrity sand cast components. Certified to EN9100:2018 and JOSCAR, and equipped with 3D sand printing, 5-axis CNC machining, CT scanning, digital radiography, and CMM metrology. Serves automotive, EV, motorsport, aerospace, defence, and petrochemical sectors.', '{"company_type":"Sand Casting","website_url":"https://finecast.co.uk/","location":"Littlehampton, West Sussex, UK","certifications":["EN9100:2018","JOSCAR","ISO 9001:2015"],"capabilities":["Sand Casting","3D Sand Printing","5-Axis CNC Machining","CT Scanning","Digital Radiography","Ultrasonic Testing","CMM Metrology","Heat Treatment","Assembly"],"industries":["Automotive","Electric Vehicles","Motorsport","Aerospace","Defence","Petrochemical","Architectural"],"lead_time":null,"min_order":null,"employees":"50-99","established":2002,"materials":["Aluminium Alloys","Austenitic Stainless Steel","SG Iron","Grey Iron","Copper-Based Alloys"],"key_equipment":["3D Sand Printing","5-Axis CNC Machining Centre","CT Scanner"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Harrison Castings Ltd', 'A Leicester aluminium casting foundry founded in 1911 and one of the largest aluminium sand casting companies in the UK, producing over 1,500 tonnes of aluminium sand castings annually with approximately 95 employees. Certified to BS ISO 9001:2015 and accredited by BSI and UKAS, the company offers aluminium sand casting up to 350 kg per component, gravity die casting, CNC machining, heat treatment, and pattern making. Serves defence, medical, energy, diesel engine, and construction equipment sectors.', '{"company_type":"Sand Casting","website_url":"https://www.harrisoncastings.com/","location":"Leicester, Leicestershire, UK","certifications":["BS ISO 9001:2015","UKAS Accreditation"],"capabilities":["Aluminium Sand Casting","Gravity Die Casting","CNC Machining","Heat Treatment","Pattern Making","Sand Core Making","Thermal Sand Reclamation","Casting Testing & Inspection"],"industries":["Defence","Medical","Energy","High-Horsepower Engines","Construction Equipment","Compressors & Pumps"],"lead_time":null,"min_order":null,"employees":"50-99","established":1911,"materials":["Aluminium Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Archibald Young Ltd', 'A family-owned Scottish foundry established in 1959 in Kirkintilloch, near Glasgow, producing copper-based, iron, and aluminium alloy castings from 0.1 kg to 500 kg across three generations of family ownership. Certified to ISO 9001 and operating from two sites in Kirkintilloch and Motherwell, the company supplies impellers, pump casings, bearings, gears, and marine components to engineering, pump and valves, marine, fisheries, and power generation sectors. The only full-service non-ferrous sand casting foundry of its kind in Scotland.', '{"company_type":"Sand Casting","website_url":"https://www.archibaldyoung.co.uk/","location":"Kirkintilloch, Glasgow, Scotland, UK","certifications":["ISO 9001"],"capabilities":["Sand Casting","Pattern Making","CNC Machining"],"industries":["Engineering","Pumps & Valves","Marine","Fisheries","Power Generation","Creative Arts"],"lead_time":null,"min_order":null,"employees":"10-49","established":1959,"materials":["Copper-Based Alloys","Aluminium Alloys","Iron Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Westley Group Ltd', 'A West Midlands casting and machining group based in Cradley Heath employing 300 people across four UK manufacturing facilities, with specialist subsidiaries including Meighs Westley (sand casting), Spun Alloys (centrifugal casting), Walter Frank, and Francis Birkett Group. Specialises in heat, wear, and corrosion-resistant cast components using sand casting and centrifugal casting processes up to 16 tonnes, with integrated finish machining, NDT, and assembly capabilities. Serves aerospace, oil and gas, power generation, naval defence, and architectural sectors.', '{"company_type":"Centrifugal Casting","website_url":"https://westleygroup.co.uk/","location":"Cradley Heath, West Midlands, UK","certifications":["ISO 9001","AS9100"],"capabilities":["Centrifugal Casting","Sand Casting","CNC Finish Machining","NDT","Assembly"],"industries":["Aerospace","Oil & Gas","Power Generation","Naval Defence & Marine","Fire Equipment & Safety","Architectural"],"lead_time":null,"min_order":null,"employees":"250-499","established":null,"materials":["Heat-Resistant Alloys","Wear-Resistant Alloys","Corrosion-Resistant Alloys"],"key_equipment":["Centrifugal Casting Machines (up to 16 tonne cast weight)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cerdic Foundries Ltd', 'A Somerset sand casting foundry certified to ISO 9001:2015 and Lloyd''s Register, producing a broad range of ferrous and non-ferrous sand castings from 1 kg to 2,000 kg across three flexible production lines. Specialises in advanced iron grades including Austempered Ductile Iron (ADI), Spheroidal Graphite Iron (SGI), and Compacted Graphite Iron (CGI), as well as nickel aluminium bronze and high-chrome heat-resistant steels. Serves automotive, defence, energy, renewables, marine, and architectural markets.', '{"company_type":"Sand Casting","website_url":"https://www.cerdicfoundries.co.uk/","location":"Chard, Somerset, UK","certifications":["ISO 9001:2015","Lloyd''s Register"],"capabilities":["Sand Casting","Pattern Making","Core Making","CNC Machining","Heat Treatment","Chemical Analysis","Metallography","Assembly"],"industries":["Automotive","Defence","Energy","Renewables","Marine","Architectural","Transportation"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Austempered Ductile Iron (ADI)","Spheroidal Graphite Iron","Compacted Graphite Iron","Grey Cast Iron","Aluminium Alloys","Copper Alloys","Nickel Aluminium Bronze","High-Chrome Heat-Resistant Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');


