INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', '3T Additive Manufacturing Ltd', 'One of the UK''s longest-established and most highly certified metal additive manufacturing service bureaus, founded in 1999 in Newbury, Berkshire. Operates a wide range of EOS metal AM systems including large-frame M400-4 machines, serving aerospace, medical, motorsport, and defence sectors. Part of the BEAMIT Group since 2021, enabling serial production for major global OEMs across the UK, Europe, US, and Japan.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.3t-am.com","location":"Newbury, Berkshire, UK","certifications":["ISO 9001","AS9100","ISO 13485"],"capabilities":["Metal DMLS/SLM","Metal Additive Manufacturing","Design for AM","Rapid Prototyping","Serial Production","Post-Processing"],"industries":["Aerospace","Medical","Motorsport","Defence","Automotive"],"lead_time":null,"min_order":null,"employees":"10-49","established":1999,"materials":["Aluminium AlSi10Mg","Titanium Ti6Al4V","Inconel 718","Inconel 625","Stainless Steel 316L","Cobalt Chrome","Maraging Steel"],"key_equipment":["EOS M400-4","EOS M290"],"data_source":"company_website + industry_news","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', '3DPRINTUK Ltd', 'London-based polymer 3D printing service bureau established in 2011, specialising in SLS, Multi Jet Fusion, and SAF technologies for low-volume batch production. Claims the UK''s highest MJF capacity with 10 HP 5210 Pro Series machines producing over one million custom parts per year. Carbon neutral and Climate Partner certified, serving manufacturing, aerospace, defence, medical, and creative industries.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.3dprint-uk.co.uk","location":"Leyton, London, UK","certifications":["ISO 9001:2015","ISO 14001:2015","JOSCAR"],"capabilities":["SLS","MJF (HP Multi Jet Fusion)","SAF (Selective Absorption Fusion)","Low-Volume Production","Batch Manufacturing"],"industries":["Aerospace","Defence","Medical","Automotive","Manufacturing","Marine & Subsea","Creative"],"lead_time":null,"min_order":null,"employees":"10-49","established":2011,"materials":["Nylon PA12","TPU","Nylon PA11 Eco"],"key_equipment":["HP 5210 Pro Series (x10)","EOS Formiga P110","EOS P396","Stratasys H350"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Protolabs UK Ltd', 'World-leading digital manufacturing service provider headquartered in Telford, Shropshire, offering rapid 3D printing, CNC machining, and injection moulding with parts delivered as fast as one day. The UK base employs around 450 people and offers the full range of additive technologies including metal DMLS, SLA, SLS, MJF, PolyJet, and Carbon DLS. Heavily certified for aerospace and medical supply chains.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.protolabs.com/en-gb","location":"Telford, Shropshire, UK","certifications":["ISO 9001:2015","ISO 14001:2015","AS9100","JOSCAR"],"capabilities":["Metal DMLS","SLA","SLS","MJF","PolyJet","Carbon DLS","CNC Machining","Injection Moulding"],"industries":["Aerospace","Defence","Medical","Automotive","Robotics & Automation","Consumer Electronics","Industrial"],"lead_time":null,"min_order":null,"employees":"250-499","established":2005,"materials":["Aluminium","Cobalt Chrome","Inconel","Stainless Steel","Titanium","Maraging Steel","Nylon PA12","ABS","Polycarbonate","TPU","PEEK","PEI"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Laser Prototypes Europe Ltd (LPE)', 'The longest-established rapid prototyping and additive manufacturing bureau in the UK and Ireland, founded in Belfast in 1991. Offers an exceptionally broad process portfolio spanning SLA, SLS, DMLS, DLP, HPS, vacuum casting, CNC machining, and finishing. Holds the rare triple certification of ISO 9001, ISO 13485, and AS9100, qualifying it to serve medical and aerospace supply chains at the highest tier.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.laserproto.com","location":"Belfast, Northern Ireland, UK","certifications":["ISO 9001","ISO 13485","AS9100"],"capabilities":["SLA","SLS","DMLS","DLP","HPS (Hybrid Photosynthesis)","Vacuum Casting","CNC Machining","3D Scanning","Painting & Finishing"],"industries":["Medical","Aerospace","Automotive","Motorsport","Consumer Goods","Defence","Film & Animation","Architecture"],"lead_time":null,"min_order":null,"employees":"10-49","established":1991,"materials":["Aluminium","Stainless Steel","Titanium","Nylon PA12","Photopolymer Resins","Rubber-like materials"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Progressive Technology Ltd', 'Newbury, Berkshire-based precision manufacturer with almost 40 years of experience, combining metal additive manufacturing (DMLS) with multi-axis CNC machining from a single production site running 24/7. Supplies 80% of the Formula 1 grid and is trusted by leading aerospace, defence, and medical OEMs. Holds AS9100 and ISO 9001 across its Additive Manufacturing division and is JOSCAR registered.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://progressive-technology.co.uk","location":"Newbury, Berkshire, UK","certifications":["ISO 9001","AS9100","JOSCAR"],"capabilities":["Metal DMLS","5-Axis CNC Machining","Design for AM","End-Use Production Parts","Post-Processing"],"industries":["Motorsport (F1)","Aerospace","Defence","Medical"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Aluminium AlSi10Mg","Titanium Ti6Al4V","Inconel 718","Stainless Steel","Cobalt Chrome"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Digital Manufacturing Centre Ltd (DMC)', 'Industry-defining production facility and innovation hub located at Silverstone Park, Northamptonshire, officially launched in 2021. Operates metal DMLS and polymer AM systems alongside machining, heat treatment, and CMM inspection in a 2,000 sq metre facility. Serves aerospace, space, defence, motorsport, and medical sectors with end-use-ready components, and is recognised as a top 1% approved supplier globally by APWORKS for Scalmalloy parts.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.digitalmanufacturingcentre.com","location":"Silverstone Park, Towcester, Northamptonshire, UK","certifications":null,"capabilities":["Metal DMLS (multi-laser)","Polymer AM","5-Axis CNC Machining","Heat Treatment","CMM Inspection","3D Scanning"],"industries":["Aerospace","Space","Defence","Motorsport","Automotive","Medical","Marine"],"lead_time":null,"min_order":null,"employees":"10-49","established":2021,"materials":["Aluminium","Titanium","Scalmalloy","Inconel 718","Inconel 625","Stainless Steel","Copper","TiCP"],"key_equipment":["Renishaw multi-laser DMLS machines","5-axis CMM"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Graphite Additive Manufacturing Ltd', 'Aylesbury, Buckinghamshire service bureau founded in 2012 with deep roots in Formula 1, providing SLS, SLA, and MJF 3D printing to motorsport, automotive, and aerospace customers. The only UK bureau offering proprietary Sinterworx C6 SLS material, and developer of the exclusive Sinterworx G4 material. Achieves 90% of parts delivered within 3 working days, with a fast-track EXPRESS service available.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.graphite-am.co.uk","location":"Aylesbury, Buckinghamshire, UK","certifications":null,"capabilities":["SLS","SLA","MJF (HP Multi Jet Fusion)","Post-Processing","Vapour Smoothing"],"industries":["Motorsport","Automotive","Aerospace","Architecture","Marine"],"lead_time":null,"min_order":null,"employees":"10-49","established":2012,"materials":["Nylon PA12","Sinterworx C6 (proprietary)","Sinterworx G4 (proprietary)","Carbon-reinforced Nylon","SLA Watershed XC 11122","DSM PerFORM Ceramic"],"key_equipment":null,"data_source":"company_website + industry_news","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Malcolm Nicholls Ltd (MNL 3D)', 'One of Europe''s most established rapid prototyping and 3D printing service bureaus, founded in 1970 and based in Bidford-on-Avon, Warwickshire. Operates across three Midlands sites with some of the UK''s largest 3D printers (800x800x600mm build envelope) running 24/7. Provides SLA, SLS, and FDM services alongside vacuum casting, CNC machining, and injection moulding, with engineering-grade materials including PEEK, ULTEM, and PEKK.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://mnl.co.uk","location":"Bidford-on-Avon, Warwickshire, UK","certifications":null,"capabilities":["SLA (large-format)","SLS","FDM","Vacuum Casting","CNC Machining","Vacuum Forming","Investment Casting Patterns"],"industries":["Aerospace","Defence","Automotive","Medical","Architecture","Consumer Goods","Foundry"],"lead_time":null,"min_order":null,"employees":"50-99","established":1970,"materials":["Nylon PA12","PEEK","ULTEM 1010","PEKK","ABS","Polycarbonate","Transparent Resins"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
