INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Midlands 3D Printing Ltd', 'Stone, Staffordshire-based HP Multi Jet Fusion specialist founded in 2018, operating an automated production facility where MJF machines run 24/7, making it one of the most efficient MJF operations in the UK. ISO 9001 certified, JOSCAR registered, and a member of the HP Digital Manufacturing Network. In 2024 volume 3D print manufacturing became the majority of their business, serving automotive, defence, healthcare, and marine sectors.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://midlands3d.com","location":"Stone, Staffordshire, UK","certifications":["ISO 9001","JOSCAR","Cyber Essentials"],"capabilities":["MJF (HP Multi Jet Fusion)","FDM","SLS TPU","3D Scanning","Reverse Engineering","Vapour Smoothing"],"industries":["Automotive","Defence","Healthcare","Engineering & Manufacturing","Consumer Products","Marine"],"lead_time":null,"min_order":null,"employees":"1-9","established":2018,"materials":["Nylon PA12","TPU"],"key_equipment":["HP Multi Jet Fusion machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
