INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Laser Additive Solutions Ltd', 'Doncaster-based specialist in laser-based metal manufacturing processes, offering Direct Metal Laser Sintering (DMLS), laser welding, laser cladding, and laser hardening backed by over 30 years of combined laser processing experience. ISO 9001:2015 accredited and JOSCAR registered since 2024, qualifying the company for aerospace, defence, and security supply chains. Serves precision engineering industries requiring complex metal AM parts.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.laseradditivesolutions.co.uk","location":"New Rossington, Doncaster, UK","certifications":["ISO 9001:2015","JOSCAR"],"capabilities":["Metal DMLS","Laser Welding","Laser Cladding","Laser Hardening"],"industries":["Aerospace","Defence & Security","Precision Engineering"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website + industry_news","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'DEEP Manufacturing Ltd', 'Avonmouth, Bristol-based large-scale Wire Arc Additive Manufacturing (WAAM) specialist established in 2023, operating one of the world''s largest concentrations of WAAM systems with twenty Wire Arc DED machines capable of producing components up to 6.2 metres in diameter. Europe''s first company to receive full DNV Approval of Manufacture for WAAM, covering pressure vessels and hull structures. Serves aerospace, defence, energy, and maritime sectors.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.deepmanufacturing.com","location":"Avonmouth, Bristol, UK","certifications":["DNV Approval of Manufacture (AoM) for WAAM","BSI certified"],"capabilities":["Wire Arc Additive Manufacturing (WAAM)","Wire Arc DED","Large-Format Metal AM (up to 6.2m diameter)","Pressure Vessel Manufacturing"],"industries":["Aerospace & Defence","Energy","Maritime"],"lead_time":null,"min_order":null,"employees":"10-49","established":2023,"materials":["Steel","Titanium alloys","Aluminium alloys"],"key_equipment":["Wire Arc DED machines (x20)"],"data_source":"company_website + industry_news","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'WAAM3D Ltd', 'Cranfield University spin-out based in Milton Keynes, incorporated in 2018, pioneering Wire Arc Additive Manufacturing (WAAM) technology commercially. Supplies proprietary RoboWAAM hardware systems, WAAMCtrl operating software, WAAMPlanner, and WAAMSim, as well as providing contract manufacturing, consultancy, and training services. Serves aerospace, energy, marine, and mining sectors with large-scale metal components at significantly lower cost than conventional manufacturing.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://www.waam3d.com","location":"Milton Keynes, Buckinghamshire, UK","certifications":null,"capabilities":["Wire Arc Additive Manufacturing (WAAM)","AM Systems Manufacturing (RoboWAAM)","AM Software Development","Contract Manufacturing","AM Consultancy & Training"],"industries":["Aerospace","Energy","Marine","Mining","Research & Development"],"lead_time":null,"min_order":null,"employees":"10-49","established":2018,"materials":["Steel (ER70)","Titanium Ti6Al4V","Aluminium alloys"],"key_equipment":["RoboWAAM systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Additure Ltd', 'Preston, Lancashire metal additive manufacturing service company established in 2022 as a venture by Kingsbury machine tool suppliers, combining Laser Powder Bed Fusion (LPBF) and Wire Arc Additive Manufacturing (WAAM) under one roof. ISO 9001:2015 certified with LRQA Facility Qualification and Cyber Essentials, serving clients including Rolls-Royce, Boeing, Airbus, and BAE Systems. Recently installed a Gefertec arc80X WAAM machine for large-scale metal components.', '{"company_type":"3D Printing / Additive Manufacturing","website_url":"https://additure.co.uk","location":"Bamber Bridge, Preston, Lancashire, UK","certifications":["ISO 9001:2015","LRQA Facility Qualification","Cyber Essentials"],"capabilities":["Metal LPBF (Laser Powder Bed Fusion)","Wire Arc Additive Manufacturing (WAAM)","Feasibility Planning","Post-Processing","CMM Inspection"],"industries":["Aerospace","Defence","Motorsport","Nuclear","General Engineering"],"lead_time":null,"min_order":null,"employees":"10-49","established":2022,"materials":null,"key_equipment":["SLM 500 (quad laser)","Gefertec arc80X WAAM","Gefertec Arc405"],"data_source":"company_website + industry_news","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

