INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cleveland Circuits Ltd', 'With over 55 years of electronics production experience based in Teesside, Cleveland Circuits provides PCB supply (single-sided through to flex and rigid-flex), SMT and through-hole assembly, box build, and conformal coating. Their sister company Connect-2 Technology handles cable assemblies, making them a full-service supply partner for defence, renewables, marine, and subsea industries.', '{"company_type":"PCB Fabrication / EMS","website_url":"https://www.pcb.co.uk","location":"Teesside, North East England, UK","certifications":["ISO 9001:2015","IPC-A-610","IPC-J-STD-001","IPC-A-620","JOSCAR","Made in Britain"],"capabilities":["SMT Assembly","Through-Hole Assembly","Bare PCB Supply","Flex PCB","Rigid-Flex PCB","Box Build","Conformal Coating","3D AOI","Cable Assembly"],"industries":["Defence","Aerospace","Renewables","Marine","Medical","Subsea","Power Distribution"],"lead_time":null,"min_order":null,"employees":"50-99","established":1968,"materials":["FR4","Flex / Polyimide"],"key_equipment":["3D AOI","SPI inspection system"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Axis Electronics Ltd', 'Axis Electronics is the UK''s leading high-reliability EMS company, founded in 1995 and now part of the Cicor Group. Operating from Bedford with approximately 180 employees, they specialise in complex PCBA, system assembly, and test for defence, aerospace, and space sectors. The company holds AS9100D, ISO 9001, Cyber Essentials Plus, and JOSCAR accreditations, and is MOD approved for handling protected information.', '{"company_type":"Electronics Manufacturing Services (EMS)","website_url":"https://www.axis-electronics.com","location":"Bedford, Bedfordshire, England, UK","certifications":["AS9100D","ISO 9001","Cyber Essentials Plus","JOSCAR","SC21 Silver"],"capabilities":["Complex PCBA","System Assembly","Production Test Development","Environmental Screening","In-Process Verification","Box Build"],"industries":["Defence","Aerospace","Space","Automotive","Oil & Gas","Communications"],"lead_time":null,"min_order":null,"employees":"100-249","established":1995,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rockford (AQ Wiring Systems)', 'Founded in 1978 and operating from three UK sites in Suffolk, Nottinghamshire, and Wiltshire, Rockford is the UK''s largest independent provider of cable assemblies, wiring harnesses, and system-level electrical equipment. They serve aerospace, defence, and industrial markets including nuclear and transportation, holding AS9100, IPC-J-STD-001, and IPC/WHMA-A-620 accreditations.', '{"company_type":"Wire Harness / Cable Assembly","website_url":"https://www.rockford.co.uk","location":"Rendlesham, Suffolk, England, UK (also Worksop, Nottinghamshire and Salisbury, Wiltshire)","certifications":["ISO 9001","AS9100","IPC-J-STD-001","IPC/WHMA-A-620","Cyber Essentials","JOSCAR"],"capabilities":["Cable Assembly","Wiring Harnesses / Looms","Box Build","Control Panels","Hermetically Sealed Harnesses","Over-Braided Harnesses","High-Speed Connectivity"],"industries":["Aerospace","Defence","Industrial","Transportation","Nuclear"],"lead_time":null,"min_order":null,"employees":"250-499","established":1978,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cable Harnesses UK Ltd', 'Based on the Trostre Industrial Park in Llanelli, South Wales, Cable Harnesses UK has manufactured electrical wiring harnesses, cable assemblies, and electro-mechanical sub-assemblies since 1990. They are ISO 9001:2015 and ISO 14001 certified, IPC/WHMA-A-620 trained, and support both low-volume and mass production for over 50 worldwide customers across 20+ industries including automotive, renewable energy, and medical.', '{"company_type":"Wire Harness / Cable Assembly","website_url":"https://www.cableharnessesuk.com","location":"Llanelli, Carmarthenshire, South Wales, UK","certifications":["ISO 9001:2015","ISO 14001","IPC/WHMA-A-620","RoHS","REACH"],"capabilities":["Wiring Harnesses","Cable Assemblies","Electro-Mechanical Sub-Assemblies","PCB Assembly","Box Build","Panel Wiring","Ribbon Cable","Kitting"],"industries":["Automotive","Renewable Energy","Oil & Gas","Medical","Telecoms","Marine","Rail","Agriculture","Security"],"lead_time":null,"min_order":null,"employees":"10-49","established":1990,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'WH Kemp & Sons Ltd', 'Established in 1967 in Westbury, Wiltshire, WH Kemp is one of the UK''s longest-serving wire harness, cable assembly, and potting specialists with 60+ skilled technicians. They hold UL, IPC, and ISO 9001 certifications and report a 99.9%+ first-pass quality rate. Their specialisms include potting and encapsulation alongside control panels and box builds, serving medical, nuclear, defence, and automotive customers.', '{"company_type":"Wire Harness / Cable Assembly","website_url":"https://www.whkemp.co.uk","location":"Westbury, Wiltshire, England, UK","certifications":["ISO 9001","UL","IPC"],"capabilities":["Wire Harnesses","Cable Assemblies","Control Panels","Box Build","Potting & Encapsulation","Testing & Inspection"],"industries":["Medical","Defence","Nuclear","Automotive","Marine","Oil & Gas","Robotics","Scientific"],"lead_time":null,"min_order":null,"employees":"50-99","established":1967,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Teepee Electrical Ltd', 'Operating from Bloxwich in the West Midlands, Teepee Electrical has supplied cable harnesses, wiring looms, and panel assemblies for over 25 years with a workforce of 50+ staff. ISO 9001:2015 accredited, they serve automotive, rail, renewable energy, and agricultural machinery customers from a dual-site operation. Their core market is bespoke harness design and manufacture including EV and bus/coach vehicle conversions.', '{"company_type":"Wire Harness / Cable Assembly","website_url":"https://teepeeelectrical.co.uk","location":"Bloxwich, West Midlands, England, UK","certifications":["ISO 9001:2015"],"capabilities":["Cable Harnesses","Wiring Looms","Panel Assemblies","Prototype Manufacturing","EV Wiring","Vehicle Conversion Harnesses"],"industries":["Automotive","Rail","Renewable Energy","Agriculture"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hayakawa International UK Ltd', 'Hayakawa is a global automotive wire harness and cable assembly manufacturer with UK operations established in 1993 on Llay Industrial Estate in North Wales. Part of a 10,000+ employee global group spanning 24 locations across 10 countries, the UK facility manufactures custom wire harnesses for automotive and industrial OEMs. All sites are certified to ISO 9001 and ISO 14001; the UK facility also holds UL certification.', '{"company_type":"Wire Harness / Cable Assembly","website_url":"https://www.hayakawa.co.uk","location":"Llay, Wrexham, North Wales, UK","certifications":["ISO 9001","ISO 14001","UL"],"capabilities":["Automotive Wire Harnesses","Cable Assemblies","Custom Harness Design"],"industries":["Automotive","Industrial"],"lead_time":null,"min_order":null,"employees":"100-249","established":1993,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Protronix EMS Ltd', 'A Luton-based contract electronics manufacturer with heritage since 1986, Protronix EMS provides end-to-end PCB prototyping, SMT and through-hole assembly, cable assembly, and component sourcing for safety-critical and demanding-environment applications. ISO 9001 registered and IPC-A-610 compliant, they serve prestigious UK customers across multiple sectors from defence to industrial.', '{"company_type":"Electronics Manufacturing Services (EMS)","website_url":"https://protronix.co.uk","location":"Luton, Bedfordshire, England, UK","certifications":["ISO 9001","IPC-A-610"],"capabilities":["PCB Prototyping","SMT Assembly","Through-Hole Assembly","BGA","Fine Pitch","Cable Assembly","Turnkey Manufacturing","Component Sourcing"],"industries":["Defence","Industrial","Safety-Critical"],"lead_time":null,"min_order":null,"employees":"10-49","established":1986,"materials":null,"key_equipment":["SMT pick and place","High-resolution inspection systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
