INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Simtek EMS Ltd', 'Established in 2004 and based in Margate, Kent, Simtek EMS (now part of Westwood EMS following a 2024 acquisition) specialises in the manufacture of life-enhancing, life-protecting, and life-saving electronic products. They offer SMT and through-hole PCB assembly from 0201 to BGA, cable and wiring assembly, conformal coating, ultrasonic welding, and complete box build, certified to ISO 9001 and ISO 13485.', '{"company_type":"Electronics Manufacturing Services (EMS)","website_url":"https://simtekems.co.uk","location":"Margate, Kent, England, UK","certifications":["ISO 9001","ISO 13485","IPC-A-610","J-STD-001","RoHS","CE"],"capabilities":["SMT Assembly","Through-Hole Assembly","BGA","Fine Pitch","Cable Assembly","Conformal Coating","Ultrasonic Welding","Box Build","Pad Printing"],"industries":["Medical","Life Sciences","Industrial","Consumer Electronics"],"lead_time":null,"min_order":null,"employees":"10-49","established":2004,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'EC Electronics Ltd', 'Founded in 1984 and headquartered in Basingstoke, Hampshire, EC Electronics is a long-established EMS provider offering PCB assembly, cable assembly, box build, conformal coating, potting, and overmoulding for healthcare, automotive, and industrial markets. They hold ISO 9001, ISO 14001, IPC-A-610, IPC/WHMA-A-620, and ATEX certifications, and operate additional facilities in the Netherlands and Romania.', '{"company_type":"Electronics Manufacturing Services (EMS)","website_url":"https://ecelectronics.com","location":"Basingstoke, Hampshire, England, UK","certifications":["ISO 9001","ISO 14001","IPC-A-610","IPC/WHMA-A-620","ATEX 2014/34/EU"],"capabilities":["PCB Assembly","Cable Assembly","Box Build","Conformal Coating","Potting & Encapsulation","Overmoulding","Design Support","Product Fulfilment"],"industries":["Healthcare","Automotive","Industrial","IoT","Capital Equipment"],"lead_time":null,"min_order":null,"employees":"100-249","established":1984,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Contract Production Ltd', 'Based on the Thornton Road Industrial Estate in Pickering, North Yorkshire, Contract Production is an ISO 9001:2015 and IPC-A-610 certified CEM with over 15 years of experience established in 2009. They deliver SMT and through-hole PCB assembly, box build, conformal coating, device programming, and final testing for environmental monitoring, wearables, audio-visual, and industrial test and measurement markets.', '{"company_type":"Electronics Manufacturing Services (EMS)","website_url":"https://contractproduction.co.uk","location":"Pickering, North Yorkshire, England, UK","certifications":["ISO 9001:2015","IPC-A-610","IPC Certified In-House Trainer"],"capabilities":["SMT Assembly","Through-Hole Assembly","Box Build","Conformal Coating","Device Programming","Functional Testing","Turnkey EMS"],"industries":["Environmental Monitoring","Wearable Technology","Audio-Visual","Industrial Test & Measurement"],"lead_time":null,"min_order":null,"employees":"10-49","established":2009,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'PCB Train (Newbury Electronics Ltd)', 'PCB Train is the trading name of Newbury Electronics Ltd, a Berkshire-based PCB fabricator and assembler with over 65 years of industry experience. They manufacture 1 to 12 layer boards in standard and quick-turn lead times, offering silver and ENIG surface finishes, SMT and through-hole assembly, BGA placement, and automated conformal coating. Certified to EN9100/AS9100D, ISO 9001, ISO 13485, ISO 14001, UL, and JOSCAR.', '{"company_type":"PCB Fabrication / EMS","website_url":"https://www.pcbtrain.co.uk","location":"Newbury, Berkshire, England, UK","certifications":["EN9100 / AS9100D","ISO 9001","ISO 13485:2016","ISO 14001:2015","ISO 45001:2018","UL","JOSCAR","Cyber Essentials"],"capabilities":["PCB Fabrication (1-12 layers)","SMT Assembly","Through-Hole Assembly","BGA","Conformal Coating (CNC selective)","AOI","Laser Stencils"],"industries":["Aerospace","Defence","Medical","Space","Industrial"],"lead_time":null,"min_order":null,"employees":"50-99","established":1987,"materials":["FR4"],"key_equipment":["Automated multi-axis CNC selective coating machine","SMD pick and place"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dynamic EMS Ltd', 'Tracing its roots to 1957 and rebranded as Dynamic EMS in 2005, this Dunfermline-based Scottish CEM operates from the Hillend and Donibristle Industrial Estate in Fife. They provide agile, tailor-made electronics manufacturing services spanning design to distribution, with particular expertise serving power and process industries and water and wastewater markets. The company positions itself as a ''Product Solutions Architect'' enabling scale, scope, and speed.', '{"company_type":"Electronics Manufacturing Services (EMS)","website_url":"https://dynamic-ems.com","location":"Dunfermline, Fife, Scotland, UK","certifications":null,"capabilities":["PCB Assembly","Box Build","Electronic Product Build","Prototype through Production","Test","Fulfilment"],"industries":["Power & Process","Water & Wastewater","Aviation","Communications","Energy","Healthcare","Safety & Security"],"lead_time":null,"min_order":null,"employees":"10-49","established":1957,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
