INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'MARL International Ltd', 'Based at MARL Business Park in Ulverston, Cumbria, MARL International has over 50 years of experience designing and manufacturing LED indicators and specialist electronic lighting systems. They serve defence, rail, marine, offshore, and industrial control markets to MILSPEC, DefStan, and STANAG standards, and hold Network Rail PADS approval. Their expertise spans custom LED hardware, embedded software, and full regulatory certification support.', '{"company_type":"LED / Lighting Manufacturing","website_url":"https://www.leds.co.uk","location":"Ulverston, Cumbria, England, UK","certifications":["MILSPEC","DefStan","STANAG","Network Rail PADS","EN Standards"],"capabilities":["LED Indicator Design & Manufacture","Specialist LED Lighting Systems","Custom Hardware & Software","Regulatory Certification Support"],"industries":["Defence","Rail","Marine","Offshore","Industrial Control","Water Treatment","Film & Photography"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
