INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'NORCO Composites & GRP', 'NORCO is one of the UK''s largest composite structure manufacturers, with over 40 years of experience producing lightweight composite and GRP assemblies for aerospace, defence, marine, and automotive sectors. Operating from multiple facilities in Poole, Dorset, they offer prepreg autoclave manufacture, resin infusion, pattern and mould tooling, CNC machining, and kitting. Major clients include Rolls-Royce, BAE Systems, and Airbus.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.norco.co.uk","location":"Poole, Dorset, UK","certifications":["AS9100D","ISO 9001","ISO 14001","Cyber Essentials Plus"],"capabilities":["Prepreg Layup","Autoclave Curing","Resin Infusion","GRP Laminating","Pattern & Mould Tooling","CNC Machining","Kitting"],"industries":["Aerospace","Defence","Marine","Automotive","Medical","Renewable Energy"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["Carbon Fiber","Glass Fiber","Epoxy Prepreg","GRP"],"key_equipment":["Autoclave","CNC Machine"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pentaxia Ltd', 'Pentaxia is a Derby-based advanced composites and precision engineering company serving some of the world''s most demanding industries. They specialise in composite tooling, component manufacture, press tooling, and full assembly for aerospace, defence, and automotive sectors. The company operates four 5-axis CNC machines and holds both AS9100 and IATF 16949 accreditations.', '{"company_type":"Composites & Advanced Materials","website_url":"https://pentaxia.com","location":"Derby, Derbyshire, UK","certifications":["AS9100","IATF 16949","JOSCAR"],"capabilities":["Composite Tooling","Prepreg Layup","5-Axis CNC Machining","Press Tooling","Assembly","Pattern Making"],"industries":["Aerospace","Defence","Automotive","Motorsport"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["Carbon Fiber","Glass Fiber","Epoxy Prepreg"],"key_equipment":["4x 5-Axis CNC Machines","Autoclave"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Atlas Composite Technologies Ltd', 'Atlas Composite Technologies is a well-established UK composites manufacturer based in Ilkeston, Derbyshire, with a strong reputation for producing complex flight-critical composite components for aerospace, motorsport, defence, and space flight. Their capabilities span from master pattern and mould tool production through to finished components, supported by an ISO Class 7 clean room, autoclave curing, and 5-axis machining. They hold AS9100 accreditation and supply Formula 1 teams and satellite communications customers.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.atlascomposites.com","location":"Ilkeston, Derbyshire, UK","certifications":["AS9100"],"capabilities":["Prepreg Layup","Autoclave Curing","5-Axis CNC Machining","CMM Inspection","Composite Tooling","CNC Kit Cutting"],"industries":["Aerospace","Motorsport","Defence","Space","Satellite Communications"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Carbon Fiber","Glass Fiber","Epoxy Prepreg"],"key_equipment":["ISO Class 7 Clean Room","Autoclave","5-Axis CNC Router","CMM"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'South Coast Composites Ltd', 'South Coast Composites (SCC) is a Chichester-based AS9100-accredited manufacturer of precision composite moulds and components for aerospace, Formula 1, defence, and supercar customers. They operate three autoclaves, a clean room, and advanced 3D laser scanning inspection. The company specialises in prepreg mould making, carbon fibre component manufacture, and complex bonded assemblies using aerospace adhesives and Rohacell foam cores.', '{"company_type":"Composites & Advanced Materials","website_url":"https://sccomposites.co.uk","location":"Chichester, West Sussex, UK","certifications":["AS9100"],"capabilities":["Prepreg Layup","Autoclave Curing","Composite Tooling","Mould Making","Bonded Assemblies","3D Laser Scanning","Clean Room Manufacturing"],"industries":["Aerospace","Formula 1","Motorsport","Automotive","Defence"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Carbon Fiber","Epoxy Prepreg","Rohacell Foam Core"],"key_equipment":["3x Autoclaves","3D Laser Scanning System","Clean Room"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SHD Composite Materials Ltd', 'SHD Composite Materials is a Sleaford, Lincolnshire-based prepreg manufacturer producing a wide range of tooling and component prepregs suitable for autoclave, press, and oven curing. Founded in 2010 and now part of Cambium Biomaterials, they operate wide-format UD prepreg lines (up to 1500mm) and film coating equipment, with a dedicated R&D technical centre. They hold EN9100:2018 aerospace certification and serve motorsport, aerospace, automotive, marine, and rail sectors.', '{"company_type":"Composites & Advanced Materials","website_url":"https://shdcomposites.com","location":"Sleaford, Lincolnshire, UK","certifications":["EN9100:2018"],"capabilities":["Prepreg Manufacture","UD Prepreg Production","Film Coating","Tooling Prepregs","Out-of-Autoclave Prepregs"],"industries":["Motorsport","Aerospace","Automotive","Marine","Rail","Defence"],"lead_time":null,"min_order":null,"employees":"50-99","established":2010,"materials":["Carbon Fiber Prepreg","Glass Fiber Prepreg","Epoxy Resin Systems","Sustainable Bio-based Prepregs"],"key_equipment":["Wide-Format UD Prepreg Line (1500mm)","Film Coating Lines","Hot Melt Fabric Laminating Lines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Crosby Composites Ltd', 'Crosby Composites, founded in 1982 and based in Brackley, Northamptonshire (near Silverstone), is described as the UK''s leading one-stop carbon fibre composite company. They manufacture complex, high-quality carbon fibre parts for Formula 1, automotive hypercars, and medical applications, with in-house capabilities spanning conceptual design, bespoke tooling, kit-cutting, autoclave curing, CNC machining, and spray painting. The company employs approximately 245 people across two Northamptonshire sites.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.crosbycomp.co.uk","location":"Brackley, Northamptonshire, UK","certifications":["ISO 9001","IATF 16949"],"capabilities":["Prepreg Layup","Autoclave Curing","CNC Kit Cutting","Composite Tooling","CNC Machining","Spray Painting"],"industries":["Formula 1","Motorsport","Automotive","Medical"],"lead_time":null,"min_order":null,"employees":"250-499","established":1982,"materials":["Carbon Fiber","Epoxy Prepreg"],"key_equipment":["Large Autoclaves","CNC Machine Shop","Laminating Clean Room"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sigmatex (UK) Ltd', 'Sigmatex is a Runcorn, Cheshire-based pioneer in the design, development, and manufacture of carbon fibre textiles for the composites industry, with over 30 years of experience. They produce woven fabrics, spread tow fabrics, multiaxial non-crimp fabrics (NCF), unidirectional fabrics, and recycled carbon fibre fabrics, supporting a wide range of grades including heavy tow and recycled content. The company employs 145 people at its UK headquarters and holds ISO 14001 and ISO 45001 certifications.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.sigmatex.com","location":"Runcorn, Cheshire, UK","certifications":["ISO 14001","ISO 45001"],"capabilities":["Carbon Fiber Weaving","NCF Manufacture","UD Fabric Production","Spread Tow Fabric","Recycled Fiber Fabrics"],"industries":["Aerospace","Automotive","Motorsport","Marine","Industrial"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["Carbon Fiber","Recycled Carbon Fiber","Aramid Fiber"],"key_equipment":["Carbon Fiber Weaving Looms","NCF Multiaxial Lines","UD Production Lines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Prodrive Composites Ltd', 'Prodrive Composites is a Milton Keynes-based advanced composites manufacturer founded in 2011, and the first UK composites business to achieve IATF 16949 automotive certification. Operating from a 40,000 sq ft facility, they manufacture structural and non-structural composite components for automotive, motorsport, aerospace, marine, and defence sectors. Key clients include Aston Martin, Lotus, Bentley, Jaguar Land Rover, and McLaren. They operate two autoclaves, two large ovens, and full CNC machining up to 5-axis.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.prodrive.com/composites","location":"Milton Keynes, Buckinghamshire, UK","certifications":["IATF 16949","ISO 9001"],"capabilities":["Prepreg Layup","Autoclave Curing","Oven Curing","Composite Tooling","5-Axis CNC Machining","CMM Laser-Scan Inspection","Clean Room Manufacturing"],"industries":["Automotive","Motorsport","Aerospace","Marine","Defence"],"lead_time":null,"min_order":null,"employees":"100-249","established":2011,"materials":["Carbon Fiber","Glass Fiber","Flax Fiber","Epoxy Prepreg"],"key_equipment":["2x Autoclaves (200°C/100 PSI rated)","2x Large Ovens","5-Axis CNC Router","CMM Laser Scanner"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pultrex Ltd', 'Pultrex is an Essex-based manufacturer with over 40 years of experience producing both pultruded composite profiles and the pultrusion, pull-winding, and filament winding machines used to make them. Their profiles division runs five pultrusion lines 24 hours a day, six days a week, producing GRP angle sections, box sections, channels, tubes, rods, and flat bars for automotive, aerospace, defence, civil engineering, and construction applications. Pultrex is described as the UK''s only pultrusion machine manufacturer and supplies equipment to over 20 countries.', '{"company_type":"Composites & Advanced Materials","website_url":"https://pultrex.com","location":"Manningtree, Essex, UK","certifications":["ISO 9001"],"capabilities":["Pultrusion","Pull Winding","Filament Winding","Pultrusion Machine Manufacture","Custom Profile Design"],"industries":["Automotive","Aerospace","Defence","Civil Engineering","Railways","Construction"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Glass Fiber Reinforced Polymer (GRP)","Carbon Fiber Reinforced Polymer","Thermoplastic Composites","Thermoset Composites"],"key_equipment":["5x Pultrusion Lines","Pull Winding Machines","Filament Winding Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lamplas (Durham) Ltd', 'Lamplas is among the largest GRP and solid surface moulders in the UK, operating from 70,000 sq ft of production space in Consett, County Durham since 1970. Now part of the MPM Group, they produce GRP components for the leisure, caravan, motorhome, transport, construction, and commercial vehicle markets using hand layup, spray layup, RTM, and vacuum press infusion processes. They employ approximately 80 staff and have completed over 2,000 projects for commercial, domestic, and leisure clients.', '{"company_type":"Composites & Advanced Materials","website_url":"https://lamplas.com","location":"Consett, County Durham, UK","certifications":null,"capabilities":["Hand Layup","Spray Layup","Resin Transfer Moulding (RTM)","Vacuum Press Infusion (VPI)","Pattern Making","Mould Tool Manufacture","Solid Surface Casting"],"industries":["Leisure","Caravan & Motorhome","Transport","Construction","Commercial Vehicles"],"lead_time":null,"min_order":null,"employees":"50-99","established":1970,"materials":["Glass Fiber (GRP)","Polyester Resin","Solid Surface Material"],"key_equipment":["RTM Injection Equipment","Vacuum Infusion Systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Carbon Fibre Composites Ltd', 'Carbon Fibre Composites Ltd is a Norfolk-based specialist in carbon fibre and composite product manufacture, offering in-house design, engineering, and temperature-controlled clean room production. They fabricate carbon fibre components using hand layup, RTM, RTML, and vacuum-assisted resin infusion for automotive, motorsport, marine, oil and gas, and renewable energy sectors. The company also operates sister company Fusion Composites for GRP production.', '{"company_type":"Composites & Advanced Materials","website_url":"https://carbonfibrecomposites.co.uk","location":"Great Ellingham, Norfolk, UK","certifications":null,"capabilities":["Hand Layup","RTM","Resin Infusion","VARTM","Composite Repairs","CNC Machining","Clean Room Manufacturing"],"industries":["Automotive","Motorsport","Marine","Oil & Gas","Renewable Energy","Electronics"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Carbon Fiber","Glass Fiber (GRP)","Epoxy Resin"],"key_equipment":["Temperature-Controlled Clean Room","RTM Equipment","Vacuum Infusion Systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'KS Composites Ltd', 'KS Composites is a Leicestershire-based advanced composites and GRP manufacturer celebrating 40 years of operation, offering technical partnership from concept through to production. They are ISO 9001:2015 accredited and have manufactured race car chassis and high-performance automotive components including work on the Jaguar Project 8. The company serves motorsport, automotive, and other advanced composite sectors from their Old Dalby facility.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.kscomposites.com","location":"Old Dalby, Leicestershire, UK","certifications":["ISO 9001:2015"],"capabilities":["Composite Design & Engineering","Chassis Fabrication","GRP Moulding","Prepreg Layup"],"industries":["Motorsport","Automotive"],"lead_time":null,"min_order":null,"employees":"10-49","established":1984,"materials":["Carbon Fiber","Glass Fiber (GRP)","Advanced Composites"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SGL Carbon Fibres Ltd', 'SGL Carbon Fibres operates the UK''s primary polyacrylonitrile (PAN)-based carbon fibre production site at Muir of Ord in the Scottish Highlands. This well-established and flexible European competence centre produces a broad range of carbon fibre products including heavy tow, oxidized fibres, carbonized fibres, and short-cut fibres, with lines upgraded to produce 24k carbon fibres. The site is certified to ISO 9001 and the aerospace standard AS9100, and has formed a partnership with the UK''s National Composites Centre.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.sglcarbon.com","location":"Muir of Ord, Ross-shire, Scotland, UK","certifications":["ISO 9001","AS9100"],"capabilities":["Carbon Fiber Production","PAN Oxidation","Carbonization","Short-Cut Fiber Production","Heavy Tow Production"],"industries":["Aerospace","Automotive","Defence","Industrial"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["PAN-based Carbon Fiber","Oxidized Fiber","Carbonized Fiber","Short-Cut Carbon Fiber"],"key_equipment":["Oxidation Lines","Carbonization Furnaces","24k Fiber Production Lines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'International Syalons (Newcastle) Ltd', 'International Syalons, based in Wallsend, Tyne & Wear, is the UK''s leading manufacturer of sialon and silicon nitride-based advanced technical ceramics, with over 40 years of experience. Now part of the CALSITHERM group, they manufacture thermocouple protection tubes, heater and riser tubes, extrusion dies, and weld location pins engineered for extreme thermal and mechanical environments in foundry, metal forming, and chemical process industries. The company holds ISO 9001 certification.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.syalons.com","location":"Wallsend, Tyne & Wear, UK","certifications":["ISO 9001"],"capabilities":["Sialon Ceramic Manufacture","Silicon Nitride Manufacture","Precision Ceramic Machining","Custom Ceramic Component Design"],"industries":["Foundry","Metal Forming","Chemical Processing","Wear Applications","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":1979,"materials":["Silicon Nitride","Sialon","Zirconia","Alumina","Silicon Carbide"],"key_equipment":["High-Temperature Sintering Furnaces","Precision Diamond Grinding Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Precision Ceramics Ltd', 'Precision Ceramics is a Birmingham-based manufacturer and machiner of custom advanced technical ceramic components, founded in 1992. They supply ultra-precisely machined ceramic parts in alumina, zirconia, silicon nitride, silicon carbide, boron nitride, boron carbide, Macor, and Shapal for demanding applications in nuclear energy, medical devices, particle accelerators, space propulsion, and aerospace. The company holds ISO 9001:2015 certification and has additional facilities in the USA and Europe.', '{"company_type":"Composites & Advanced Materials","website_url":"https://precision-ceramics.com/uk","location":"Birmingham, West Midlands, UK","certifications":["ISO 9001:2015"],"capabilities":["Technical Ceramic Manufacture","Precision CNC Ceramic Machining","Ceramic Grinding","Custom Component Design","Application Engineering"],"industries":["Nuclear Energy","Medical","Space","Aerospace","Semiconductor","High Energy Physics"],"lead_time":null,"min_order":null,"employees":"10-49","established":1992,"materials":["Alumina","Zirconia","Silicon Nitride","Silicon Carbide","Boron Nitride","Boron Carbide","Macor","Shapal Hi M Soft","Aluminium Nitride"],"key_equipment":["CNC Ceramic Machining Centres","Diamond Grinding Equipment","Sintering Furnaces"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Conbury Composites Ltd', 'Conbury Composites is an Isle of Wight-based GRP manufacturer founded in 1969 with over 50 years of experience producing glass reinforced plastic mouldings for marine, electrical, industrial, and leisure sectors. They make boat hulls, specialist mouldings for the electricity industry, industrial tanks, electronic component covers, and leisure items, operating their own pattern making shop and manufacturing all mould tools in-house. They offer production runs and one-off commissions and service customers across the Isle of Wight, Hampshire, and surrounding areas.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.conbury.co.uk","location":"Isle of Wight, Hampshire, UK","certifications":null,"capabilities":["Hand Layup GRP Moulding","Pattern Making","Mould Tool Manufacture","One-Off & Production Runs"],"industries":["Marine","Electrical Infrastructure","Industrial","Leisure"],"lead_time":null,"min_order":null,"employees":"10-49","established":1969,"materials":["Glass Fiber (GRP)","Polyester Resin"],"key_equipment":["Pattern Making Shop","In-House Mould Tools"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Premier Composites Ltd', 'Premier Composites is a Lincolnshire-based GRP mouldings manufacturer established in 1992, operating a 25,000 sq ft facility in Boston. They produce glass fibre reinforced plastic mouldings using epoxy, polyester, and phenolic resin systems via hand laminating, vacuum infusion, and vacuum bagging techniques, including fire-retardant grades to BS476 standards. Their products include aerofoils, vehicle body panels, theme park structures, and custom GRP assemblies, serving theme parks, automotive, marine, transport, and leisure sectors with over 50 fabrication and finishing staff.', '{"company_type":"Composites & Advanced Materials","website_url":"https://www.premiercomposites.co.uk","location":"Boston, Lincolnshire, UK","certifications":null,"capabilities":["Hand Laminating","Vacuum Infusion","Vacuum Bagging","Pattern & Mould Making","CNC Services","Assembly","Fire-Retardant GRP"],"industries":["Theme Parks & Leisure","Automotive","Marine","Transport (Rail, Bus & Coach)","Construction"],"lead_time":null,"min_order":null,"employees":"50-99","established":1992,"materials":["Glass Fiber (GRP)","Epoxy Resin","Polyester Resin","Phenolic Resin"],"key_equipment":["Vacuum Infusion Systems","CNC Router"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');


