INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Severfield plc', 'The UK''s largest specialist structural steelwork group, operating five manufacturing facilities across the UK (Dalton, Lostock, Carnaby, Ballinamallard, Sherburn) with annual capacity of approximately 300,000 tonnes of fabricated steelwork. The company delivers complete design, fabrication, and erection services for landmark projects including The Shard, Emirates Stadium, and Wimbledon Centre Court roof. A publicly listed company on the London Stock Exchange since 1995.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.severfield.com","location":"Dalton, North Yorkshire, UK (HQ); multiple UK sites","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 CE Marking (all EXC classes)","ISO 3834"],"capabilities":["Structural Steel Fabrication","Steel Design & Engineering","BIM Modelling","Steel Erection","Shot Blasting & Painting","Nuclear & Infrastructure Steelwork"],"industries":["Commercial & Industrial","Nuclear","Infrastructure","Transport","Healthcare","Education"],"lead_time":null,"min_order":null,"employees":"500+","established":1978,"materials":["Structural Steel","High Strength Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'William Hare Group Ltd', 'The UK''s second largest structural steelwork contractor by turnover, founded in 1888 and family-owned, with fabrication facilities at Bury, Scarborough, Newport, Rotherham, and Thorp Arch. The company has delivered projects in over 50 countries including 20 Fenchurch Street and 201 Bishopsgate in London. Certified to EN 1090 Execution Class 4 and ISO 3834-2.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.hare.com","location":"Bury, Greater Manchester, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 EXC-4","ISO 3834-2","NHSS20","NHSS19A"],"capabilities":["Structural Steel Fabrication","Steel Erection","Steel Design","Shot Blasting & Painting","Complex Geometry Steelwork"],"industries":["Commercial","Residential","Infrastructure","Industrial"],"lead_time":null,"min_order":null,"employees":"500+","established":1888,"materials":["Structural Steel","Weathering Steel","Stainless Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Caunton Engineering Limited', 'One of the UK''s leading fully automated structural steelwork contractors fabricating in excess of 40,000 tonnes per annum from their Nottinghamshire facility, specialising in Just-in-Time manufacture. The family-owned company holds ISO 3834-2 welding quality management certification and EN 1090 Execution Class 4 accreditation. With over 50 years'' experience they serve all sectors of the construction industry.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.caunton.co.uk","location":"Moorgreen Industrial Park, Nottingham, Nottinghamshire, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 EXC-4","ISO 3834-2"],"capabilities":["Structural Steel Fabrication","Steel Design & Engineering","Steel Erection","Shot Blasting & Painting","Just-in-Time Manufacturing","CNC Processing"],"industries":["Commercial","Industrial","Retail","Healthcare","Education","Logistics"],"lead_time":null,"min_order":null,"employees":"250-499","established":1970,"materials":["Structural Steel","High Strength Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Elland Steel Structures Limited', 'A leading UK structural steel company based in Halifax, West Yorkshire, holding rare Execution Class 4 accreditation under BS EN 1090-1 and ISO 3834-2 welding quality certification. Founded in 1982, the company has built 50 years of knowledge and experience and operates from their West Yorkshire headquarters with satellite offices in Billingham and London. Elland Steel is a BCSA member and SCCS certified.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.ellandsteel.com","location":"Halifax, West Yorkshire, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 EXC-4","ISO 3834-2","BCSA Member"],"capabilities":["Structural Steel Fabrication","Tubular Steelwork","Complex Geometry Steelwork","Steel Erection","Secondary Steelwork"],"industries":["Construction","Infrastructure","Industrial","Commercial"],"lead_time":null,"min_order":null,"employees":"100-249","established":1982,"materials":["Structural Steel","Hollow Section Steel","Weathering Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Billington Structures Ltd', 'One of the UK''s leading structural steelwork contractors since 1947, with two fabrication plants in Barnsley, South Yorkshire, and one in Bristol, capable of processing over 50,000 tonnes of steel per annum. The company specialises in design, supply, fabrication and erection of projects from simple frames to complex structures in excess of 15,000 tonnes. A BCSA member led by chartered engineers.', '{"company_type":"Structural Steel Fabrication","website_url":"https://billington-structures.co.uk","location":"Wombwell, Barnsley, South Yorkshire, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 CE Marking","BCSA Member"],"capabilities":["Structural Steel Fabrication","Steel Design","Steel Erection","Shot Blasting & Painting","BIM Modelling","Tubular Steelwork (TUBECON AESS)"],"industries":["Commercial","Industrial","Infrastructure","Nuclear","Healthcare"],"lead_time":null,"min_order":null,"employees":"250-499","established":1947,"materials":["Structural Steel","Stainless Steel","Hollow Sections"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'H. Young Structures Ltd', 'A founding member of the BCSA (British Constructional Steelwork Association), part of the H. Young & Co Ltd Group which has been a trusted name in structural steelwork since 1871. Based in Wymondham, Norfolk, the company holds EN 1090 Execution Class 4 and ISO 3834-2 certifications and employs approximately 59 staff. They specialise in design, fabrication, priming, and erection of structural steelwork.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.hyoungstructures.co.uk","location":"Wymondham, Norfolk, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 EXC-4","ISO 3834-2","Constructionline Gold","BCSA Founder Member"],"capabilities":["Structural Steel Fabrication","Steel Design","Steel Erection","Tubular Steelwork","Architectural Steelwork","Machinery Frames"],"industries":["Construction","Industrial","Commercial","Refurbishment"],"lead_time":null,"min_order":null,"employees":"50-99","established":1871,"materials":["Structural Steel","Hollow Sections"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'BHC Ltd', 'A Scotland-based structural steelwork contractor operating from Carnwath, South Lanarkshire, employing over 350 staff and holding EN 1090, ISO 3834, ISO 9001, ISO 14001, and ISO 45001 certifications. BHC builds everything from agricultural buildings to complex commercial structures and shopping centres using state-of-the-art technology. The company has SCCS (Steel Construction Certification Scheme) approval.', '{"company_type":"Structural Steel Fabrication","website_url":"https://bhc.ltd.uk","location":"Medwyn Park, Edinburgh Road, Carnwath, South Lanarkshire, ML11 8HS, Scotland, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090","ISO 3834","SCCS Approved"],"capabilities":["Structural Steel Fabrication","Steel Design","Steel Erection","Portal Frames","Complex Structural Steelwork"],"industries":["Commercial","Retail","Agricultural","Industrial","Infrastructure"],"lead_time":null,"min_order":null,"employees":"250-499","established":null,"materials":["Structural Steel","Cold Rolled Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Had Fab Ltd', 'One of the UK''s leading structural engineering and metal fabrication companies, founded in 1993 and based in East Lothian, Scotland. Had Fab operates four sites covering over 55,000 square metres including two 120-metre covered manufacturing lines, holding EN 1090 Execution Class 4, ISO 3834-2, ISO 9001, ISO 14001, and ISO 45001 certifications. The company specialises in tubular steelwork, towers, masts, and specialist structural steel.', '{"company_type":"Structural Steel Fabrication","website_url":"https://hadfab.co.uk","location":"Macmerry Industrial Estate, Tranent, East Lothian, EH33 1RD, Scotland, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 EXC-4","ISO 3834-2","BCSA Member"],"capabilities":["Structural Steel Fabrication","Aluminium Fabrication","Tubular Steelwork","Towers & Masts","Architectural Steelwork","Section Bending","Castellated Beams","Surface Treatment"],"industries":["Power Transmission & Distribution","Rail","Renewables & Energy","Civils & Infrastructure","Commercial"],"lead_time":null,"min_order":null,"employees":"250-499","established":1993,"materials":["Structural Steel","Aluminium","Weathering Steel"],"key_equipment":["Two 120m covered manufacturing lines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Walter Watson Ltd', 'The largest family-owned structural steel fabricator on the island of Ireland, established in 1975 and operating from a 21-acre site in Castlewellan, County Down, Northern Ireland with 35,000m² of covered manufacturing and storage. The company holds CE Execution Class 4, ISO 9001, ISO 14001, ISO 45001, and ISO 50001 certifications and is a BCSA member. Walter Watson serves healthcare, education, retail, industrial, and power sectors.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.walter-watson.co.uk","location":"Castlewellan, County Down, BT31 9JQ, Northern Ireland, UK","certifications":["ISO 9001:2015","ISO 14001:2015","ISO 45001:2018","ISO 50001:2018","EN 1090 EXC-4","BCSA Member"],"capabilities":["Structural Steel Fabrication","Steel Design & Detailing (Tekla BIM)","CNC Processing","Shot Blasting & Painting","Steel Erection","Steel Reinforcement","Industrial Cranes"],"industries":["Healthcare","Education","Retail","Industrial","Airports","Power Stations"],"lead_time":null,"min_order":null,"employees":"250-499","established":1975,"materials":["Structural Steel","High Strength Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Painter Brothers', 'A major British structural steelwork fabricator and one of the world''s leading producers of bolted lattice steelwork, founded in Hereford in 1920. Operating from a 50,000m² facility in Hereford with one of the largest machining capabilities in the UK, Painter Brothers annually produces more than 8,000 tonnes of steel. The company holds EN 1090 EXC-3, ISO 3834-2, and all major management system certifications, and is a Balfour Beatty group company.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.painterbrothers.com","location":"Holmer Road, Hereford, HR4 9SW, Wales/West Midlands border, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","EN 1090 EXC-3","ISO 3834-2","BCSA Member"],"capabilities":["Structural Steel Fabrication","Lattice Steelwork","Transmission Towers","Telecom Masts","CNC Machining","Rail Infrastructure Steelwork"],"industries":["Power Distribution","Rail","Nuclear","Renewable Energy","Telecommunications"],"lead_time":null,"min_order":null,"employees":"250-499","established":1920,"materials":["Structural Steel","High Strength Steel","Weathering Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Leach Structural Steelwork Ltd', 'A large structural steel fabricator based in Preston, Lancashire, holding EN 1090 Execution Class 3, ISO 9001, and ISO 3834-3 certifications. The company is CE Marked for design and fabrication and offers on-site steel erection services, serving clients throughout the UK construction industry. Leach Structural Steelwork is both a BCSA member and SCCS certified company.', '{"company_type":"Structural Steel Fabrication","website_url":"https://www.leachsteel.com","location":"Brockholes Way, Claughton on Brock, Preston, Lancashire, PR3 0PZ, UK","certifications":["ISO 9001","EN 1090 EXC-3","ISO 3834-3","BCSA Member","SCCS Certified"],"capabilities":["Structural Steel Fabrication","Steel Design","Steel Erection","CE Marked Steelwork"],"industries":["Construction","Industrial","Commercial"],"lead_time":null,"min_order":null,"employees":"100-249","established":null,"materials":["Structural Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'WEC Group Ltd', 'One of the largest contract manufacturing companies in Europe, growing from a welding and fabrication shop in Darwen, Lancashire over 45 years ago. WEC Fabrication holds ISO 9001:2015, BS EN 1090, and RISQS certifications with over 125 skilled welders and craneage up to 30 tonnes across multiple Lancashire and UK facilities totalling 760,000 sq ft. The group serves nuclear, aerospace, automotive, offshore, rail, and motorway sectors.', '{"company_type":"Welding & Structural Fabrication","website_url":"https://www.wec-group.com","location":"Darwen, Lancashire, UK (multiple sites)","certifications":["ISO 9001:2015","EN 1090 EXC-4","RISQS","ISO 3834"],"capabilities":["Structural Steel Fabrication","Coded Welding","Heavy Fabrication","Stainless Steel Fabrication","Pressure Vessel Fabrication","Large Machining","Laser Cutting","Architectural Metalwork"],"industries":["Nuclear","Aerospace","Automotive","Offshore","Rail","Construction"],"lead_time":null,"min_order":null,"employees":"500+","established":null,"materials":["Mild Steel","Stainless Steel","Aluminium","Exotic Alloys"],"key_equipment":["30-tonne craneage","Laser cutting systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'LTi Metaltech Ltd', 'An Oxfordshire-based precision welding and pressure vessel manufacturer established in 2005, with approximately 100 specialist staff. The company has manufactured over 15,000 cryogenic pressure vessel sets for MRI systems and holds certifications including ASME U Stamp, AD 2000 Merkblatt HP0, ISO 3834-2, EN 1090, ISO 9001, ISO 14001, and ISO 45001. Part of the European LTi Metalltechnik Group, they operate advanced robotic and semi-automated welding systems alongside one of the UK''s largest coded welder teams.', '{"company_type":"Coded Welding & Pressure Vessel Fabrication","website_url":"https://lti-metaltech.com","location":"Oxfordshire, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","ISO 3834-2","EN 1090","ASME U Stamp","AD 2000 Merkblatt HP0","PED 2014/68/EU","EN 13445"],"capabilities":["Pressure Vessel Manufacture","Coded TIG Welding","Coded MIG/MAG Welding","Plasma Arc Welding","Robotic Welding","Waterjet Cutting","Laser Cutting","CNC Edge Preparation","Stainless Steel & Aluminium Rolling"],"industries":["Healthcare / MRI","Energy","Utilities","Nuclear Fusion","Cryogenics"],"lead_time":null,"min_order":null,"employees":"100-249","established":2005,"materials":["Stainless Steel","Aluminium","Titanium","Duplex","Copper"],"key_equipment":["Robotic welding cells","Waterjet cutting"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ECF Special Alloys Ltd', 'A specialist welding fabricator of exotic materials established in 1993 in Nottinghamshire, holding ISO 9001:2015, ISO 3834-2, ASME U Stamp, and National Board of Boiler & Pressure Vessel Inspectors certifications. ECF Special Alloys fabricates pressure vessels and process equipment from titanium, stainless steel, duplex, super duplex, and nickel alloys for the offshore oil and gas and petrochemical industries. Their two covered workshops total 8,000 sq ft with 5- and 10-tonne crane capacity.', '{"company_type":"Coded Welding & Pressure Vessel Fabrication","website_url":"https://ecfspecialalloys.co.uk","location":"Carlton-in-Lindrick, Worksop, Nottinghamshire, S81 9LB, UK","certifications":["ISO 9001:2015","ISO 3834-2","ASME U Stamp","National Board Certificate","PD 5500","ASME Section VIII Div 1"],"capabilities":["TIG Welding","MMA Welding","MIG/MAG Welding","Coded Welding","Pressing & Rolling","Profiling","NDT Inspection","Exotic Material Fabrication"],"industries":["Offshore Oil & Gas","Petrochemical"],"lead_time":null,"min_order":null,"employees":"10-49","established":1993,"materials":["Titanium","Stainless Steel","Duplex","Super Duplex","Nickel Alloys","Inconel"],"key_equipment":["10-tonne overhead crane","5-tonne overhead crane"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Holden''s CVE Limited', 'A Lancashire-based mechanical engineering company founded in 1967, providing pressure vessel design, fabrication, testing, and installation services with over 50 years of experience. The company holds ISO 9001, CE Marking to EN 1090 (EXC-3), and various industry accreditations including RISQS and SafeContractor. Operating from Leyland, their facilities include overhead cranes up to 30-tonne capacity serving aerospace, chemical, food, nuclear, oil and gas, and rail sectors.', '{"company_type":"Heavy Fabrication & Pressure Vessel","website_url":"https://holdensengineering.co.uk","location":"Centurion Way Industrial Estate, Farington, Leyland, Lancashire, PR25 4GU, UK","certifications":["ISO 9001:2015","EN 1090 EXC-3","RISQS","SafeContractor","CHAS","IPAF"],"capabilities":["Pressure Vessel Design & Fabrication","Heavy Plate Fabrication","Coded Welding","Stainless Steel Fabrication","Pipework Prefabrication","Plant Manufacture","Site Installation"],"industries":["Aerospace","Chemical Processing","Food & Beverage","Nuclear","Oil & Gas","Rail","Pharmaceutical"],"lead_time":null,"min_order":null,"employees":"50-99","established":1967,"materials":["Mild Steel","Stainless Steel","Duplex","Aluminium"],"key_equipment":["30-tonne overhead cranes"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Barnshaws Section Benders Limited', 'Described as the world''s largest metal bending company, Barnshaws was founded in 1969 in the West Midlands and holds ISO 9001, EN 1090 (SCCS approved), and BCSA membership. With facilities in Oldbury, Coseley, Manchester, Hamilton (Scotland), Germany, and Poland, they offer section bending of lengths up to 35 metres, plate rolling up to 100mm thick, induction bending, and press braking up to 12m long. They serve construction, oil and gas, offshore, rail, and architectural sectors.', '{"company_type":"Tube/Section Bending & Structural Fabrication","website_url":"https://www.barnshaws.com","location":"Oldbury, West Midlands, UK (multiple UK sites)","certifications":["ISO 9001","EN 1090 SCCS Approved","BCSA Member","The Aluminium Federation"],"capabilities":["Section Bending (up to 35m)","Plate Rolling (up to 100mm thick)","Press Braking (up to 12m)","Induction Bending","Aluminium Bending","Pipe & Tube Bending"],"industries":["Construction","Oil & Gas","Offshore","Rail","Automotive","Architectural"],"lead_time":null,"min_order":null,"employees":"100-249","established":1969,"materials":["Structural Steel","Aluminium","Stainless Steel","Hollow Sections"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Listertube (James Lister & Sons Limited)', 'A Redditch-based tube and bar manipulation specialist established in 1874, with ISO 9001, ISO 14001, and ISO 45001 certifications. Operating from a 10,000 sq ft facility, Listertube provides tube bending, end forming, laser and plasma cutting, flow drilling, and finishing services for diameters from 4mm to 76mm. The company serves gas heating, HVAC, hydraulics, automotive, aerospace, furniture, and agricultural equipment industries.', '{"company_type":"Tube Fabrication & Bending","website_url":"https://www.listertube.com","location":"Bartleet Road, Redditch, Worcestershire, B98 0DG, UK","certifications":["ISO 9001","ISO 14001","ISO 45001"],"capabilities":["Tube Bending (4-76mm diameter)","Bar Bending","End Forming","Laser Cutting","Plasma Cutting","Flow Drilling","Tube Cleaning","Assembly & Finishing"],"industries":["Gas Heating","HVAC","Hydraulics","Automotive","Aerospace","Furniture","Agricultural Equipment"],"lead_time":null,"min_order":null,"employees":"10-49","established":1874,"materials":["Mild Steel","Stainless Steel","Aluminium","Copper","Bundy Tube"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Stroud Metal Company Ltd', 'A Gloucestershire-based precision metal pressings manufacturer with over 100 years of operations at their Stonehouse site, privately owned and family-run. The company specialises in deep draw metal pressings using high-speed Bruderer progressive die presses and transfer presses, producing approximately 15 million parts per press and exporting globally to Europe, Asia, and the Americas. Industries served include automotive, consumer goods, industrial, and pharmaceutical.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://www.stroudmetal.co.uk","location":"Brunel Way, Stonehouse, Gloucestershire, GL10 3SX, UK","certifications":null,"capabilities":["Deep Draw Pressings","High-Speed Progressive Die Pressing","Transfer Pressing","Metal Stamping","Hybrid Metal-Plastic Components","In-house Finishing"],"industries":["Automotive","Consumer Goods","Industrial","Pharmaceutical"],"lead_time":null,"min_order":null,"employees":"100-249","established":1926,"materials":["Mild Steel","Stainless Steel","Aluminium","Copper","Brass"],"key_equipment":["High-speed Bruderer progressive die presses","Transfer presses"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Braime Pressings Ltd', 'A Leeds-based deep draw presswork specialist with over 135 years of manufacturing experience, established 1888, and a subsidiary of Braime Group PLC (AIM listed). The company produces over 3.5 million deep-drawn components annually using multi-stage progression and transfer presswork with robot technology. Braime Pressings is IATF-ISO certified and operates from their Hunslet Road facility in Leeds, West Yorkshire.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://braimepressings.com","location":"Hunslet Road, Leeds, West Yorkshire, LS10 1JZ, UK","certifications":["ISO 9001","IATF 16949"],"capabilities":["Deep Draw Pressings (up to 230mm depth)","Multi-Stage Progression Pressing","Transfer Pressing","High Volume Stamping","Sub-Assembly Manufacture","Robotic Technology"],"industries":["Automotive","General Engineering","Industrial"],"lead_time":null,"min_order":null,"employees":"50-99","established":1888,"materials":["Mild Steel","Stainless Steel","Aluminium","Copper"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Frank Dudley Ltd', 'One of the UK''s largest independent presswork companies, established 1948 in Birmingham, serving major automotive OEMs including Jaguar, Land Rover, JCB, Ford, Nissan, and Honda as a preferred second-tier supplier. The company operates presses from 25 to 630T in single action and progression press lines, plus 600T tandem lines and robotic CO2 weld cells with up to 350KVA resistance welding capacity. Services include metal pressings, deep drawn components, stamping, tool making, and robotic welding.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://www.frankdudley.com","location":"Queens Road, Aston, Birmingham, B6 7NH, UK","certifications":["SGS Quality Certified"],"capabilities":["Metal Pressings","Deep Draw Components","Progressive Die Stamping","Robotic Welding","Spot Welding","Projection Welding","CO2 Welding","Tool Making"],"industries":["Automotive","Commercial Vehicles","White Goods","DIY"],"lead_time":null,"min_order":null,"employees":"100-249","established":1948,"materials":["Mild Steel","High Strength Steel","Stainless Steel","Aluminium"],"key_equipment":["25-630T single action and progression presses","600T tandem press lines","Robotic CO2 weld cells"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cotmor Tool & Presswork Co Ltd', 'A family-owned West Midlands presswork specialist established in 1953 with over 70 years of experience, ISO 9001:2015 accredited and operating from a 15,000 sq ft facility in Brierley Hill, Dudley. The company offers precision presswork, deep drawn pressings up to 200mm deep, and bespoke metal forming with a 400-tonne press capacity. Cotmor serves customers across the UK and internationally.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://www.cotmor.co.uk","location":"Brierley Hill, Dudley, West Midlands, UK","certifications":["ISO 9001:2015"],"capabilities":["Deep Drawn Pressings (up to 200mm depth)","Progressive Metal Stamping","Precision Presswork","Bespoke Metal Forming","Tool Design & Making"],"industries":["General Engineering","Automotive","Industrial"],"lead_time":null,"min_order":null,"employees":"10-49","established":1953,"materials":["Mild Steel","Stainless Steel","Aluminium","Copper"],"key_equipment":["400-tonne press"],"data_source":"company_website","data_confidence":"medium","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ADM Pressings Ltd', 'A Northeast England precision metal pressing and fabrication specialist tracing its roots to a Vickers Armstrong division established in 1956, reformed as ADM Pressings through a management buy-out in 2009. Operating from a 305,000 sq ft state-of-the-art facility in Newcastle upon Tyne with approximately 300 skilled engineers, they hold ISO 9001 and IATF 16949 certifications. The company is a tier one supplier to automotive and off-highway OEMs including JCB, Jaguar, and Land Rover.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://www.admpressings.co.uk","location":"Scotswood Road, Newcastle upon Tyne, NE15 6BZ, UK","certifications":["ISO 9001","IATF 16949","ISO 45001"],"capabilities":["Metal Pressings","Press Fabrication","Industrial Powder Coating","Robotic Welding","Robotic Roller Hemming","5-Axis Laser Cutting","2D Laser Cutting","Sub-Assembly Production"],"industries":["Automotive","Off-Highway","Commercial Vehicles"],"lead_time":null,"min_order":null,"employees":"250-499","established":1956,"materials":["Mild Steel","High Strength Steel","Aluminium"],"key_equipment":["1,600-tonne hydraulic presses","5-axis laser cutting systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Clamason Industries Ltd', 'A precision metal stamping and pressing specialist founded in 1947 in Kingswinford, West Midlands, with international recognition and a second plant in Slovakia. Clamason holds ISO 9001, IATF 16949, ISO 14001, ISO 13485, and FDA CFR21 Part 820 certifications making them one of the few UK presswork companies approved for medical device stamping. The company serves automotive, medical device, and eco-tech markets.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://clamason.com/en","location":"Kingswinford, West Midlands, UK","certifications":["ISO 9001","IATF 16949","ISO 14001","ISO 13485","FDA CFR21 Part 820"],"capabilities":["Precision Pressings","Progressive Stamping","Transfer Pressing","High Speed Pressing","Multi-slide Pressings","Sub-Assembly"],"industries":["Automotive","Medical Devices","Eco-Tech / EV"],"lead_time":null,"min_order":null,"employees":"100-249","established":1947,"materials":["Mild Steel","Stainless Steel","Aluminium","Copper","High Strength Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Albert Jagger Engineering Limited', 'A West Midlands metal pressings and mechanical sub-assembly manufacturer based in Bloxwich, Walsall, with over 60 years of engineering experience and ISO 9001:2015 and British Standards Quality Assurance accreditation. The company operates presses up to 150 tonnes and offers deep drawn components, CNC machining, tube manipulation, welding, and tool making. Albert Jagger Engineering serves commercial vehicles, defence, rail, emergency services, and off-highway sectors.', '{"company_type":"Metal Stamping & Presswork","website_url":"https://www.albertjaggerengineering.co.uk","location":"Vincent Works, Croxstalls Road, Bloxwich, West Midlands, WS3 2XY, UK","certifications":["ISO 9001:2015","British Standards Quality Assurance"],"capabilities":["Metal Pressings & Stampings","Deep Drawn Components","CNC Machining","Tube Manipulation","Welding","Tool Making","Sub-Assembly"],"industries":["Commercial Vehicles","Off-Highway","Defence","Rail","Emergency Services","White Goods"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Mild Steel","Stainless Steel","Aluminium"],"key_equipment":["150-tonne presses"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
