INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'LMR Geartech Ltd', 'ISO 9001 certified precision gear manufacturer established in 1994 and based in Sittingbourne, Kent. LMR Geartech specialises in CNC gear cutting with fully automated lights-out capable machinery, producing spur, helical, bevel, worm, rack and pinion, spline, sprocket gears and timing pulleys from motor pinion scale up to heavy duty crown wheels, with international customers across Europe, Asia, and North America.', '{"company_type":"Gears","website_url":"https://www.lmrgeartech.com","location":"Sittingbourne, Kent, UK","certifications":["ISO 9001"],"capabilities":["Spur Gears","Helical Gears","Bevel Gears","Worm Gears","Racks & Pinions","Splines","Sprocket Gears","Timing Pulleys"],"industries":["Machine Tooling","Textiles","Paper","Marine","Instrumentation","Lifts & Hoists","Conveyors"],"lead_time":null,"min_order":null,"employees":"10-49","established":1994,"materials":["Alloy Steel","Stainless Steel","Brass","Plastics"],"key_equipment":["CNC Gear Milling Machines","Haas CNC Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Highfield Gears Ltd', 'Founded in 1927 and headquartered in Huddersfield, West Yorkshire, Highfield Gears is one of the UK''s oldest gear manufacturers offering industrial gearbox repair, refurbishment, and gear manufacturing services. They cut spur, helical, bevel, worm, and double helical gears and have a 24/7 breakdown service, handling industrial gearboxes up to 18 tonnes with notable clients including Tata Steel, Heineken, and Anglian Water.', '{"company_type":"Gears","website_url":"https://www.highfieldgears.co.uk","location":"Huddersfield, West Yorkshire, UK","certifications":null,"capabilities":["Spur Gears","Helical Gears","Bevel Gears","Worm Gears","Double Helical Gears","Gearbox Repair","CNC Machining","Gear Spares"],"industries":["Food & Beverage","Plastics","Quarrying","Mining","Steel","Waste Treatment","Oil & Gas","Water Treatment","Brewery"],"lead_time":null,"min_order":null,"employees":"50-99","established":1927,"materials":["Brass","Phosphor Bronze","Steel","Cast Iron","Ductile Iron","Aluminium","Plastics","Nylon"],"key_equipment":["DEPO-HC 1212 CNC Machine","Two 10-Tonne Cranes"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SBT Gearing Solutions Ltd', 'Based in Bury, Greater Manchester, SBT Gearing Solutions is a specialist gear manufacturer and gearbox refurbishment company offering hobbing, shaping, profile grinding, bevel gear cutting, and worm gear production. They have acquired intellectual property and manufacturing rights to the Anderton Group range of clutches and power take-off units, serving mining, renewables, rail, agriculture, and crane industries worldwide.', '{"company_type":"Gears","website_url":"https://sbt-gears.co.uk","location":"Bury, Greater Manchester, UK","certifications":null,"capabilities":["Gear Hobbing","Gear Shaping","Profile Grinding","Bevel Gear Cutting","Worm Gear Manufacturing","Splines","Gearbox Refurbishment","Clutch Manufacturing"],"industries":["Mining","Power Generation","Renewables","Agriculture","Oil & Gas","Rail","Pulp & Paper","Crane & Lifting"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Alloy Steel","Cast Iron","Phosphor Bronze"],"key_equipment":["Gear Hobbing Machines","Profile Grinding Machines","Gear Shaping Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'NDE Clarke Pitchline Ltd', 'Coventry-based precision gear grinder established in 1969 with 45 years of experience in the gear manufacturing heartland of the UK. ISO 9001:2015 certified, they specialise in precision gear grinding of helical and spur gears up to 1000mm diameter using Reischauer and Cespel machines, alongside gear shaping, hobbing, CNC turning and driveshaft balancing for aerospace, defence, and motorsport.', '{"company_type":"Gears","website_url":"https://www.ndepower.com","location":"Coventry, West Midlands, UK","certifications":["ISO 9001:2015"],"capabilities":["Precision Gear Grinding","Gear Shaping","Gear Hobbing","Spline Grinding","CNC Turning","CNC Milling","Driveshaft Balancing","Reverse Engineering"],"industries":["Aerospace","Defence","Motorsport","Pumping Systems","Industrial","Theatre Motion Control"],"lead_time":null,"min_order":null,"employees":"10-49","established":1969,"materials":["EN8","EN9","817M40","EN24T","Inconel","Phosphor Bronze","Stainless Steel SS316L","AISI9310"],"key_equipment":["Reischauer Gear Grinding Machines","Cespel Gear Grinding Machines","Gleason Gear Checkers"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'FT Gearing Systems Ltd', 'Established in 1978 and based in Aldershot, Hampshire, FT Gearing Systems is a precision gear specialist serving the aerospace and defence sectors exclusively. They hold EN9100 (AS9100) and ISO 9001 certification alongside Nadcap EDM accreditation, manufacturing high-precision geared components from fuel management actuators to jet engine fuel pumps using Studer CNC grinders with unique CBN angled wheels.', '{"company_type":"Gears","website_url":"https://www.ftgearing.com","location":"Aldershot, Hampshire, UK","certifications":["EN9100","ISO 9001","Nadcap EDM"],"capabilities":["Gear Hobbing","Gear Grinding","CNC Gear Shaping","CNC Turning","CNC Milling","Diamond Lapping","EDM Wire Erosion","Component Assembly"],"industries":["Aerospace","Defence"],"lead_time":null,"min_order":null,"employees":"50-99","established":1978,"materials":["Aerospace Grade Alloy Steels"],"key_equipment":["Studer CNC Grinding Machines (CBN)","CNC Gear Hobbing Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
