INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'C. Brandauer & Co. Ltd', 'Founded in Birmingham in 1862, Brandauer is one of Europe''s largest precision metal stamping companies and the recipient of King''s Award for Enterprise 2024. ISO 9001, ISO 14001, and ISO 45001 certified, they specialise in high-speed precision stamped components in difficult materials and manufacture bespoke press tooling to three proprietary standards, also operating the UK''s first Precision Tooling Academy.', '{"company_type":"Toolmaking","website_url":"https://brandauer.co.uk","location":"Birmingham, West Midlands, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","King''s Award for Enterprise 2024"],"capabilities":["Precision Metal Stamping","Press Tooling","Progressive Dies","Electrical Steel Laminations","Laser Cutting","CNC Metal Forming","Wire EDM","CAD Design"],"industries":["Medical","Automotive","Electrical","Consumer Goods","Plumbing"],"lead_time":null,"min_order":null,"employees":"100-249","established":1862,"materials":["Stainless Steel","Electrical Steel","Precision Metals"],"key_equipment":["High-Speed Stamping Presses","Wire EDM","Laser Cutting Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Paragon Toolmaking Co. Ltd', 'Established in 1969 and based in Hull, East Yorkshire, Paragon Toolmaking is an ISO 9001:2015 certified designer and manufacturer of press tools, injection moulds, jigs and fixtures. They manufacture everything from small single-operation dies to large multi-stage progression tools weighing up to 10 tonnes, serving automotive, aerospace, pharmaceutical, and medical industries with an award-winning apprenticeship programme.', '{"company_type":"Toolmaking","website_url":"https://www.paragontoolmaking.com","location":"Kingston upon Hull, East Yorkshire, UK","certifications":["ISO 9001:2015","Made in Britain"],"capabilities":["Progression Tools","Stage Tools","Form Tools","Blanking Tools","Jigs & Fixtures","Transfer Tools","Deep Draw Tools","Injection Moulds","EDM","Wire Cutting","CNC Machining"],"industries":["Automotive","Aerospace","White Goods","Pharmaceutical","Medical"],"lead_time":null,"min_order":null,"employees":"50-99","established":1969,"materials":["Tool Steel","Carbide"],"key_equipment":["EDM Wire Cutting","CNC Milling","CNC Grinding"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Alliance Tooling Ltd', 'Injection mould toolmaker based in Whetstone, Leicestershire, with over 25 years of experience and more than 1,400 injection moulds manufactured. ISO 9001 and ISO 14001 certified with EcoVadis Bronze sustainability rating, Alliance Tooling offers DFM analysis, Moldflow simulation, tool design, CNC manufacturing, and a dedicated medical tooling validation centre serving automotive, medical, aerospace, and packaging sectors.', '{"company_type":"Toolmaking","website_url":"https://www.alliancetooling.co.uk","location":"Whetstone, Leicestershire, UK","certifications":["ISO 9001:2015","ISO 14001","EcoVadis Bronze","SEDEX","GTMA Member"],"capabilities":["Injection Mould Toolmaking","DFM Analysis","Moldflow Analysis","Tool Design","CNC Milling","EDM","Tool Trialling","Medical Validation","CMM Inspection"],"industries":["Aerospace","Automotive","Medical","Packaging","Defence","Consumer Products"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Aluminium Tool Steel","Hardened Steel (P20)","Tool Steel"],"key_equipment":["CNC Milling Machines","EDM Machines","CMM"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Faulkner Moulds Ltd', 'Award-winning injection mould toolmaker based in Elland, West Yorkshire, established in 1994 and three-time winner of the UK Plastics Industry ''Toolmaker of the Year'' award (2016, 2018, 2019). ISO 9001:2015 certified, Faulkner Moulds manufactures precision plastic injection mould tools to half-micron tolerances using 5-axis machining up to 3-tonne capacity and EDM electrode manufacturing.', '{"company_type":"Toolmaking","website_url":"https://www.faulknermoulds.net","location":"Elland, West Yorkshire, UK","certifications":["ISO 9001:2015","GTMA Member"],"capabilities":["Injection Mould Toolmaking","5-Axis Machining","EDM & Electrode Manufacturing","Multi-Cavity Tools","Tool Design","Product Development"],"industries":["Plastics","Medical","Electronics","Consumer Products"],"lead_time":null,"min_order":null,"employees":"10-49","established":1994,"materials":["Tool Steel","Hardened Steel"],"key_equipment":["5-Axis Machining Centre (3-tonne capacity)","CNC Sink EDM","Wire EDM"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

