INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Aluminium Surface Engineering (Brita Finish Ltd)', 'Established in 1947, Aluminium Surface Engineering (ASE) is a Coventry-based specialist in anodising processes for aluminium components, and was the first company in England to introduce the Hard Anodising process. ASE is a founder member of the International Hard Anodizing Association and holds ISO 9001 and ISO 14001 certifications. The company serves automotive, aerospace, defence, power generation, and medical device industries.', '{"company_type":"Surface Treatment","website_url":"https://ase4anodising.co.uk/","location":"Coventry, West Midlands, UK","certifications":["ISO 9001","ISO 14001"],"capabilities":["Hard Anodising","Sulphuric Anodising","Nituff Hard Anodising","Titanium Anodising","Conversion Coatings","Precision Masking"],"industries":["Automotive","Aerospace","Defence","Power Generation","Medical","Food Packaging"],"lead_time":null,"min_order":null,"employees":null,"established":1947,"materials":["Aluminium","Titanium"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
