INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Metal Finishings Limited', 'Metal Finishings Limited is a Wimborne, Dorset-based surface treatment specialist holding both ISO 9001 and AS 9100 certifications alongside NADCAP accreditation for Chemical Processing and NDT. The company provides anodising (sulphuric, hard, and chromic), conversion coatings, zinc and zinc-nickel plating, passivation, and paint spraying to the aerospace, defence, marine, and medical industries. Notable clients include Eaton, Safran, Cobham, MBDA, and Thales.', '{"company_type":"Surface Treatment","website_url":"https://www.metalfinishingsltd.co.uk/","location":"Wimborne, Dorset, UK","certifications":["ISO 9001","AS9100","NADCAP"],"capabilities":["Sulphuric Anodising","Hard Anodising","Chromic Anodising","Conversion Coatings","Zinc Plating","Zinc Nickel Plating","Passivation","Paint Spraying","NDT"],"industries":["Aerospace","Defence","Marine","Electronics","Medical"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Aluminium","Steel","Stainless Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

