VALUES ('Products', 'Post-Processing', 'Star Anodising & Finishing Ltd', 'Star Anodising & Finishing Ltd is a long-established surface treatment company founded in 1955, based in Erith, Kent. The company offers hard and decorative sulphuric anodising, zinc plating, electropolishing, aquablasting, and chemical conversion coatings to the electronics, engineering, and aerospace industries. Free delivery is provided within a 60-mile radius.', '{"company_type":"Surface Treatment","website_url":"https://staranodising.com/","location":"Erith, Kent, UK","certifications":["ISO 9001"],"capabilities":["Hard Anodising","Decorative Sulphuric Anodising","Zinc Plating","Electropolishing","Aquablasting","Dry Blasting","Conversion Coatings"],"industries":["Electronics","Engineering","Aerospace"],"lead_time":null,"min_order":null,"employees":null,"established":1955,"materials":["Aluminium","Stainless Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

