INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Allenchrome Electroplating Ltd', 'Allenchrome Electroplating Ltd is a Yorkshire-based electroplater founded in 1984, specialising in nickel, chrome, and acid zinc plating via automated rack and barrel lines. The company holds JS500 licensing and is a member of the Surface Engineering Association and the Institute of Metal Finishing. Major clients include Komatsu, JCB, Caterpillar, Rolls-Royce, Goodyear, and Renault.', '{"company_type":"Surface Treatment","website_url":"https://www.allenchrome.co.uk/","location":"Pocklington, York, Yorkshire, UK","certifications":["JS500 Licensed"],"capabilities":["Chrome Plating","Nickel Plating","Acid Zinc Plating","Conversion Coatings","Mirror Polishing","Aqua Blasting"],"industries":["Automotive","Electrical","Heavy Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":1984,"materials":["Steel","Aluminium"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

