VALUES ('Products', 'Post-Processing', 'Premier Plating Works Ltd', 'Premier Plating Works Ltd is a Birmingham-based electroplating company established in 1934, offering gold, silver, chrome, bronze, electroless nickel, and zinc plating alongside polishing and lacquering services. The company is a member of the Surface Engineering Association and serves the electronics, engineering, architectural, and manufacturing sectors across the UK.', '{"company_type":"Surface Treatment","website_url":"https://www.premierplatingworks.co.uk/","location":"Birmingham, West Midlands, UK","certifications":null,"capabilities":["Gold Plating","Silver Plating","Chrome Plating","Electroless Nickel Plating","Zinc Plating","Bronze Plating","Polishing","Lacquering","Selective Plating"],"industries":["Electronics","Engineering","Architectural","Manufacturing"],"lead_time":null,"min_order":null,"employees":null,"established":1934,"materials":["Aluminium","Stainless Steel","Steel","Brass","Copper"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Dorsetware Limited', 'Dorsetware Limited is a Poole, Dorset-based metal finishing and electroplating company established in 1969. The company provides a comprehensive range of services including chrome plating, bright nickel, gold plating, silver electroplating, hard anodising, zinc plating, passivation, and chemical blackening. An express 24-hour turnaround service is available with no minimum order quantities.', '{"company_type":"Surface Treatment","website_url":"https://www.dorsetware.com/","location":"Poole, Dorset, UK","certifications":["ISO Certified"],"capabilities":["Chrome Plating","Nickel Plating","Gold Plating","Silver Plating","Hard Anodising","Zinc Plating","Passivation","Chemical Blackening","Copper Coating","Electropolishing"],"industries":["General Engineering","Automotive","Electronics","Architectural"],"lead_time":null,"min_order":null,"employees":null,"established":1969,"materials":["Aluminium","Steel","Stainless Steel","Brass","Copper"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

