VALUES ('Products', 'Post-Processing', 'Jackson Plating Ltd', 'Jackson Plating Ltd is a Hounslow, London-based plating specialist holding ISO 9001 accreditation, offering a broad range of electrochemical and electroless plating including zinc, copper, chrome, nickel, silver, gold, tin, and stainless steel passivation. The company also provides chromic, sulphuric, and hard anodising, with a typical 3-day turnaround and complimentary local collection and delivery.', '{"company_type":"Surface Treatment","website_url":"https://www.jacksonplating.co.uk/","location":"Hounslow, London, UK","certifications":["ISO 9001"],"capabilities":["Zinc Plating","Chrome Plating","Nickel Plating","Copper Plating","Silver Plating","Gold Plating","Tin Plating","Chromic Anodising","Sulphuric Anodising","Hard Anodising","Passivation"],"industries":["Aerospace","Defence","General Manufacturing"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Aluminium","Steel","Stainless Steel","Brass","Copper"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Euro Quality Coatings Limited', 'Euro Quality Coatings Limited is a Cardiff, Wales-based powder coating specialist holding QUALICOAT, ISO 9001:2015, and ISO 14001:2015 certifications. The company offers automatic and manual powder coating, anti-graffiti and anti-microbial coating, chemical paint stripping, and chrome-free pre-treatment. Euro Quality Coatings operates on a trade-only basis serving automotive, architectural, rail, retail, medical, and office product manufacturers.', '{"company_type":"Surface Treatment","website_url":"https://www.euroqualitycoatings.co.uk/","location":"Cardiff, Wales, UK","certifications":["QUALICOAT","ISO 9001:2015","ISO 14001:2015"],"capabilities":["Powder Coating","Anti-Graffiti Coating","Anti-Microbial Coating","Chemical Paint Stripping","Chrome-Free Pre-treatment"],"industries":["Automotive","Architectural","Rail","Leisure","Retail","Medical","Building Products"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Aluminium","Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Marcote UK Ltd', 'Marcote UK Ltd is a Cannock, Staffordshire-based specialist in non-stick, PTFE/fluoropolymer, and thermal spray coatings with over 30 years of experience and ISO 9001 accreditation from the British Assessment Bureau. The company applies PTFE, plasma spray, Xylan, Halar/ECTFE, and polyurethane coatings to components serving aerospace, automotive, food, oil and gas, and pharmaceutical industries.', '{"company_type":"Surface Treatment","website_url":"https://www.marcote.co.uk/","location":"Cannock, Staffordshire, UK","certifications":["ISO 9001"],"capabilities":["PTFE Coating","Fluoropolymer Coating","Plasma Spray Coating","Xylan Coating","ECTFE Coating","Dry Lubrication","Chemical-Resistant Coatings","Abrasion-Resistant Coatings"],"industries":["Aerospace","Automotive","Food & Beverage","Pharmaceutical","Oil & Gas","Chemical","Defence","Packaging"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Aluminium","Stainless Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Plasma Coatings Limited', 'Plasma Coatings Limited (PCL) is a Derbyshire-based thermal spray coating specialist founded in 1971, holding AS9100 and NADCAP accreditations with Merit status since 2005. The company applies metal, ceramic, and composite coatings via plasma spray, HVOF, flame spray wire, and flame spray powder processes to components up to 1.5 metres in diameter. OEM approvals include Rolls-Royce, AETC, UTC Aerospace Systems, and Leonardo Aircraft.', '{"company_type":"Surface Treatment","website_url":"https://plasma-group.co.uk/","location":"Tideswell, Derbyshire, UK","certifications":["AS9100","NADCAP"],"capabilities":["Plasma Spray","HVOF Coating","Flame Spray Wire","Flame Spray Powder","Ceramic Coatings","Metal Coatings","Composite Coatings"],"industries":["Aerospace","Biomedical","Commercial Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":1971,"materials":["Steel","Aluminium","Titanium","Nickel Alloys"],"key_equipment":["Robotic Plasma Spray Systems","HVOF Systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Curtiss-Wright Surface Technologies', 'Curtiss-Wright Surface Technologies (CWST) is a global surface engineering organisation established since 1929, operating 70+ worldwide facilities including UK sites. The company offers controlled shot peening, laser peening, HVOF thermal spray, plasma spray, Parylene coating, and Everlube dry film lubricants. The company holds NADCAP, ISO 9001:2015, and AS9100 Rev D accreditations serving aerospace, oil and gas, automotive, and medical industries.', '{"company_type":"Surface Treatment","website_url":"https://www.cwst.co.uk/","location":"Multiple UK locations, UK","certifications":["NADCAP","ISO 9001:2015","AS9100 Rev D"],"capabilities":["Shot Peening","Laser Peening","HVOF Thermal Spray","Plasma Spray","Parylene Coating","Dry Film Lubricants","PTFE Coatings"],"industries":["Aerospace","Oil & Gas","Automotive","Medical"],"lead_time":null,"min_order":null,"employees":"500+","established":1929,"materials":["Steel","Titanium","Aluminium","Nickel Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Century Heat Treatment and Plating Co Ltd', 'Century Heat Treatment and Plating Co Ltd is a Birmingham-based company holding ISO 9001:2015 certification, offering combined heat treatment and electroplating services under one roof. Heat treatment services include case hardening via cyanide carburising salt baths, austempering, and harden & temper, while plating services cover zinc-nickel, zinc, bright nickel, copper, tin, silver, brass, and bronze. The company also performs hydrogen de-embrittlement and corrosion testing.', '{"company_type":"Heat Treatment","website_url":"https://www.centuryhtp.co.uk/","location":"Tyseley, Birmingham, West Midlands, UK","certifications":["ISO 9001:2015"],"capabilities":["Case Hardening","Carburising","Austempering","Harden & Temper","Zinc Nickel Plating","Zinc Plating","Nickel Plating","Silver Plating","Hydrogen De-embrittlement"],"industries":["Automotive","General Manufacturing","Fasteners"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Stainless Steel"],"key_equipment":["Salt Bath Furnaces"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Servis Heat Treatment Ltd', 'Servis Heat Treatment Ltd is a Slough, Berkshire-based heat treatment specialist with over 60 years of experience, holding ISO 9001:2015 certification. The company provides a full range of processes including through hardening, tempering, case hardening, carburising, nitriding, accelerated nitriding, vacuum hardening, annealing, normalising, and solution and precipitation hardening. A nationwide pick-up and delivery service for items up to 3.5 tonnes is available.', '{"company_type":"Heat Treatment","website_url":"https://www.servisheattreatment.co.uk/","location":"Slough, Berkshire, UK","certifications":["ISO 9001:2015"],"capabilities":["Case Hardening","Carburising","Nitriding","Nitrocarburising","Vacuum Hardening","Through Hardening","Tempering","Annealing","Normalising","Solution Treatment","Precipitation Hardening"],"industries":["Precision Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Stainless Steel","Tool Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Wallwork Group', 'Wallwork Group is the largest independent heat treatment and hard coatings company in the UK, founded in 1959 and headquartered in Bury, Greater Manchester, with additional sites in Birmingham and Cambridge. The company offers vacuum heat treatment, plasma and gas nitriding, PVD and CVD coatings, hot isostatic pressing (HIP), and vacuum brazing, and holds NADCAP, AS9100, and UKAS laboratory accreditations. The group employs approximately 300 staff and serves aerospace, biomedical, nuclear, and space sectors.', '{"company_type":"Heat Treatment","website_url":"https://wallworkht.co.uk/","location":"Bury, Greater Manchester, UK","certifications":["NADCAP","AS9100","UKAS"],"capabilities":["Vacuum Heat Treatment","Plasma Nitriding","Gas Nitriding","PVD Coating","CVD Coating","Hot Isostatic Pressing","Vacuum Brazing","Induction Hardening","Salt Bath Heat Treatment"],"industries":["Aerospace","Automotive","Biomedical","Motorsport","Nuclear","Space"],"lead_time":null,"min_order":null,"employees":"250-499","established":1959,"materials":["Steel","Titanium","Nickel Alloys","Aluminium"],"key_equipment":["Vacuum Furnaces","Quintus HIP Units","Plasma Nitriding Systems"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Summitglow Ltd', 'Summitglow Ltd is a family-owned Sheffield heat treatment specialist established in 1983 with over 40 years of experience, holding ISO 9001:2015 registration. The company operates two Sheffield sites on a 24/5 basis and provides vacuum hardening, case hardening, hardening and tempering, nitriding, and annealing services for steel components. A dedicated fleet delivers and collects work within a 150-mile radius.', '{"company_type":"Heat Treatment","website_url":"https://www.summitglow.co.uk/","location":"Sheffield, South Yorkshire, UK","certifications":["ISO 9001:2015"],"capabilities":["Vacuum Hardening","Case Hardening","Hardening & Tempering","Nitriding","Annealing","Sub-Zero Treatment"],"industries":["General Engineering","Tooling","Automotive"],"lead_time":null,"min_order":null,"employees":null,"established":1983,"materials":["Steel","High Speed Steel","Tool Steel"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'MSL Heat Treatment Limited', 'MSL Heat Treatment Limited is a Horley, Surrey-based vacuum heat treatment specialist with roots stretching back over 40 years via the acquisition of CNC Vacuum Processes. The company holds EN 9100:2018 aerospace certification and specialises in vacuum brazing, vacuum hardening, vacuum annealing, stress relieving, and precipitation hardening of components ranging from millimetres to 2 metres. Materials processed include tool steels, inconel, precipitation hardening steels, and soft magnetic alloys.', '{"company_type":"Heat Treatment","website_url":"https://www.mslheattreatment.co.uk/","location":"Horley, Surrey, UK","certifications":["EN 9100:2018"],"capabilities":["Vacuum Brazing","Vacuum Hardening","Vacuum Annealing","Vacuum Stress Relieving","Solution Treatment","Precipitation Hardening","MuMetal Brazing"],"industries":["Aerospace","General Manufacturing"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Tool Steel","High Speed Steel","Stainless Steel","Copper Alloys","Nickel Alloys","Inconel","Precipitation Hardening Steels"],"key_equipment":["Vacuum Furnaces"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
