INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Inductoheat (Tewkesbury) Ltd', 'Inductoheat (Tewkesbury) Ltd is a Gloucestershire-based specialist in induction heat treatment processes, holding ISO 9001:2015 approval and located near the M5 motorway for efficient collection and delivery. The company offers induction hardening, annealing, brazing, silver soldering, case hardening, nitriding, vacuum hardening, cryogenic treatment, and shrink fitting services. Inducto-heat also manufactures and repairs inductor coils.', '{"company_type":"Heat Treatment","website_url":"https://inducto-heat.co.uk/","location":"Tewkesbury, Gloucestershire, UK","certifications":["ISO 9001:2015"],"capabilities":["Induction Hardening","Induction Annealing","Induction Brazing","Silver Soldering","Case Hardening","Nitriding","Vacuum Hardening","Cryogenic Treatment","Shrink Fitting"],"industries":["General Engineering","Automotive","Aerospace"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Tool Steel"],"key_equipment":["Induction Hardening Machines","Vacuum Furnaces"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
