INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Scotia Surface Hardening Ltd', 'Scotia Surface Hardening Ltd is a Glasgow-based surface hardening specialist holding ISO 9001:2015 certification, offering gas nitriding, zinc phosphating, stress relieving, Xylan coatings, and Molykote dry lubricant application to engineering companies across the UK. The company has been under its current ownership since 2011 and is known for short lead times and strong customer service.', '{"company_type":"Heat Treatment","website_url":"https://www.scotiasurfacehardening.co.uk/","location":"Glasgow, Scotland, UK","certifications":["ISO 9001:2015"],"capabilities":["Gas Nitriding","Zinc Phosphating","Stress Relieving","Xylan Coating","Dry Lubricant Application"],"industries":["Engineering","Automotive","Oil & Gas"],"lead_time":null,"min_order":null,"employees":null,"established":2011,"materials":["Steel","Steel Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Post-Processing', 'Bodycote Heat Treatments Ltd', 'Bodycote is the world''s leading provider of heat treatment and thermal processing services with UK operations across sites in Macclesfield, Coventry, and Rotherham, and is a constituent of the FTSE 250 Index. The company holds NADCAP, AS9100, ISO 9001:2015, ISO 14001, IATF 16949, and MedAccred certifications across its facilities. Services include case hardening, atmospheric carburising, plasma nitriding, induction hardening, hot isostatic pressing, and vacuum processing for aerospace, automotive, medical, and power generation sectors.', '{"company_type":"Heat Treatment","website_url":"https://www.bodycote.com/","location":"Macclesfield, Cheshire, UK","certifications":["NADCAP","AS9100","ISO 9001:2015","ISO 14001","IATF 16949","MedAccred"],"capabilities":["Case Hardening","Carburising","Plasma Nitriding","Induction Hardening","Hot Isostatic Pressing","Vacuum Heat Treatment","Brazing"],"industries":["Aerospace","Automotive","Medical","Power Generation","Defence"],"lead_time":null,"min_order":null,"employees":"500+","established":null,"materials":["Steel","Aluminium","Titanium","Nickel Alloys"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Steel Service Centre Limited (SSC Laser)', 'Steel Service Centre Limited, trading as SSC Laser, is a Stafford-based laser cutting specialist established in 2000 and holding ISO 9001 and EN 1090 certifications. The company operates three flatbed lasers including a Bystronic high-power fibre laser and two tube lasers, serving agricultural, automotive, construction, oil and gas, railway, and marine industries. SSC Laser achieves 98% on-time delivery across the UK.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://ssclaser.co.uk/","location":"Hixon, Stafford, Staffordshire, UK","certifications":["ISO 9001","EN 1090"],"capabilities":["Flatbed Laser Cutting","Tube Laser Cutting","Press Braking","CAD/CAM Design"],"industries":["Agricultural","Automotive","Construction","Oil & Gas","Railway","Marine","Pharmaceutical"],"lead_time":null,"min_order":null,"employees":null,"established":2000,"materials":["Mild Steel","Stainless Steel","Aluminium"],"key_equipment":["Bystronic Fibre Laser","Adige Tube Laser","Amada CNC Press Brakes"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'The Laser Cutting Company', 'The Laser Cutting Company is a Sheffield-based laser cutting specialist established in 1981 with over 30 years of tube laser cutting experience, holding ISO 9001:2015 and BS/EN 1090-1 Level 3 certifications. The company operates a fleet of 10+ CNC fibre laser machines running 24/7, cutting sheet up to 50mm thick and 6000mm in length, and provides tube laser cutting, bevel cutting, waterjet, plasma and flame cutting, and press brake forming services.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.lasercutting.co.uk/","location":"Sheffield, South Yorkshire, UK","certifications":["ISO 9001:2015","BS/EN 1090-1"],"capabilities":["Flatbed Laser Cutting","Tube Laser Cutting","Profile Cutting","Bevel Cutting","Waterjet Cutting","Plasma Cutting","Flame Cutting","Press Brake Forming","Laser Engraving"],"industries":["General Manufacturing","Construction","Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":1981,"materials":["Mild Steel","Stainless Steel","Aluminium"],"key_equipment":["10+ CNC Fibre Laser Machines","150-Tonne Press Brakes"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

