INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Subcon Laser Cutting Ltd', 'Subcon Laser Cutting Ltd is a Nuneaton, Warwickshire-based laser cutting specialist with over three decades of industry experience, holding ISO 9001:2015, ISO 14001:2015, and EN 1090 certifications. The company operates one of the UK''s most established fibre laser fleets including an 8kW fibre laser capable of cutting materials up to 40mm thick. Subcon Laser is one of the first companies in the UK to achieve the new ISO 9001:2015 and ISO 14001:2015 accreditation.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.subconlaser.co.uk/","location":"Nuneaton, Warwickshire, UK","certifications":["ISO 9001:2015","ISO 14001:2015","EN 1090"],"capabilities":["Fibre Laser Cutting","Flatbed Laser Cutting","Press Braking","Welding"],"industries":["General Manufacturing","Construction","Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Mild Steel","Stainless Steel","Aluminium"],"key_equipment":["8kW Fibre Laser"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'WEC Laser (Laser Engineering UK Ltd)', 'WEC Laser, trading as Laser Engineering UK, is the laser cutting division of WEC Group, founded in 1979 in Darwen, Lancashire, and is described as the UK''s largest laser cutting and fabrication company. Operating 25 flatbed and tube lasers across facilities in Darwen and Knowsley, the company holds ISO 9001:2015, ISO 14001, ISO 45001, EN 1090, EN 15085, and AS9100 certifications. Services span laser cutting, waterjet cutting, plasma cutting, welding, machining, and powder coating for aerospace, rail, automotive, and construction sectors.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.laser-eng.com/","location":"Darwen, Lancashire, UK","certifications":["ISO 9001:2015","ISO 14001","ISO 45001","EN 1090","EN 15085","AS9100"],"capabilities":["Flatbed Laser Cutting","Tube Laser Cutting","Waterjet Cutting","Plasma Cutting","Welding & Fabrication","CNC Machining","Powder Coating"],"industries":["Aerospace","Rail","Automotive","Construction","Oil & Gas","Architectural"],"lead_time":null,"min_order":null,"employees":"500+","established":1979,"materials":["Mild Steel","Stainless Steel","Aluminium"],"key_equipment":["25 Flatbed & Tube Lasers"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Duright Engineering Ltd', 'Duright Engineering Ltd is a Wednesbury, West Midlands-based tube laser cutting specialist established for over 40 years, operating four Adige laser cutting machines including LT FIBER models on a 24/7 three-shift basis. The company cuts tubes from 4mm to 154mm diameter and up to 8.5 metres length in mild steel, stainless steel, aluminium, titanium, brass, and copper, producing over one million cuts per month. Secondary services include tube bending, slotting, and saw cutting.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.duright.co.uk/","location":"Wednesbury, West Midlands, UK","certifications":null,"capabilities":["Tube Laser Cutting","Angle Laser Cutting","Flat Laser Cutting","Tube Bending","Tube Slotting","Saw Cutting"],"industries":["Automotive","Furniture","Healthcare"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Mild Steel","Stainless Steel","Aluminium","Titanium","Brass","Copper"],"key_equipment":["Adige LT FIBER Tube Lasers x4"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Top Tubes Ltd', 'Top Tubes Ltd is a West Midlands-based tube manufacturer and laser cutting specialist established in 1994, operating a 14,000 sq m facility with in-house ERW tube mills and state-of-the-art BLM Adige LT7 and Trumpf 5000/7000 laser machines. The company holds ISO 9001 and ISO 14001 certifications and produces its own nitrogen on-site, processing round, square, and rectangular tubes up to 254mm diameter and 8 metres in length in mild steel, stainless steel, and aluminium.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.toptubes.co.uk/","location":"West Midlands, UK","certifications":["ISO 9001","ISO 14001"],"capabilities":["Tube Laser Cutting","ERW Tube Manufacturing","Multi-Axis 3D Cutting","Angle Cutting","Flat Cutting","Channel Cutting"],"industries":["Construction","Automotive","General Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":1994,"materials":["Mild Steel","Stainless Steel","Aluminium"],"key_equipment":["BLM Adige LT7 Laser","Trumpf 5000 Laser","Trumpf 7000 Laser"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Colstan Profiles Ltd', 'Colstan Profiles Ltd is a Dudley, West Midlands-based plasma and flame cutting specialist, part of the Roger Dyson Group, holding ISO 9001:2015 and EN 1090-1 Execution Class 2 certifications. The company operates a CNC plasma cutting bed of 9m x 3m capable of cutting material from 0.5mm to 300mm thickness, and also offers flame cutting, laser cutting, Lumsden grinding, CNC machining, normalising, stress relieving, and shot blasting. Over 1,000 tonnes of material are held in stock.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.colstanprofiles.co.uk/","location":"Dudley, West Midlands, UK","certifications":["ISO 9001:2015","EN 1090-1 Execution Class 2"],"capabilities":["Plasma Cutting","Flame Cutting","Laser Cutting","CNC Machining","Normalising","Stress Relieving","Shot Blasting"],"industries":["General Engineering","Construction","Heavy Industry"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Stainless Steel"],"key_equipment":["CNC Plasma Cutter 9m x 3m"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Technical Materials Converters Limited (TMC Waterjet)', 'Technical Materials Converters Limited, trading as TMC Waterjet, is a family-run North West England-based waterjet cutting specialist operating from a 10,000 sq ft modern facility with ISO 9001:2015 certification. The company specialises in abrasive and non-abrasive cutting of resistant materials, operating Dynamic and Dynamic XD waterjet cutting technology for 2D and 3D components.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.tmcwaterjet.co.uk/","location":"North West England, UK","certifications":["ISO 9001:2015"],"capabilities":["Abrasive Waterjet Cutting","Pure Waterjet Cutting","2D Waterjet Cutting","3D Waterjet Cutting"],"industries":["General Manufacturing","Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Aluminium","Stone","Composites","Ceramics","Plastics"],"key_equipment":["Dynamic XD Waterjet Machine"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aqua Dynamics Ltd', 'Aqua Dynamics Ltd is a family-run Oxfordshire-based waterjet cutting specialist with over 20 years of CNC waterjet experience, holding ISO 9001:2015 certification and the Made in Britain mark. The company operates two OMAX waterjet machines at 60,000 PSI, achieving tolerances to ±0.02mm on materials up to 180mm thick across metals, composites, ceramics, glass, wood, and foam. Industries served include aerospace, automotive/F1, architecture, construction, film, and defence.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.aqua-dynamics.co.uk/","location":"Watlington, Oxfordshire, UK","certifications":["ISO 9001:2015","Made in Britain"],"capabilities":["Abrasive Waterjet Cutting","Pure Waterjet Cutting","2D Cutting","3D Cutting","Prototype Cutting"],"industries":["Aerospace","Automotive","Architecture","Construction","Film","Defence","Oil & Gas"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Aluminium","Titanium","Composites","Ceramics","Glass","Stone","Plastics","Foam"],"key_equipment":["OMAX 55100 Waterjet","OMAX 5555 Waterjet"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Waterjet Precision UK Ltd', 'Waterjet Precision UK Ltd is a Cheshire-based abrasive CNC waterjet cutting company holding ISO 9001:2008 certification with approximately a decade of trading experience. The company serves a diverse range of industries across Great Britain and overseas, offering precision waterjet cutting complemented by fabrication and machining services through its sister company Harbrook Engineering Ltd.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://cncwaterjet.co.uk/","location":"Cheshire, North West England, UK","certifications":["ISO 9001:2008"],"capabilities":["Abrasive Waterjet Cutting","CNC Waterjet Cutting","CAD Services","Fabrication"],"industries":["General Manufacturing","Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Aluminium","Stone","Composites","Plastics"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Water Jet Midlands', 'Water Jet Midlands is a Stourbridge, West Midlands-based waterjet cutting specialist holding ISO 9001 certification, operating abrasive and pure waterjet systems at up to 60,000 PSI with cutting accuracy to ±0.2mm. The company serves automotive, architectural, construction, defence, and tool-and-die-making industries, and offers material supply, rapid prototyping, and production run services.', '{"company_type":"Laser & Waterjet Cutting","website_url":"https://www.waterjetmidlands.co.uk/","location":"Stourbridge, West Midlands, UK","certifications":["ISO 9001"],"capabilities":["Abrasive Waterjet Cutting","Pure Waterjet Cutting","Rapid Prototyping","Production Runs"],"industries":["Automotive","Architectural","Construction","Defence","Tool & Die Making"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Steel","Aluminium","Stone","Composites","Ceramics","Plastics"],"key_equipment":["Abrasive Waterjet Machines (60,000 PSI)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Capital Aluminium Extrusions Limited (Capalex)', 'Capital Aluminium Extrusions Limited, trading as Capalex, is a Cleator Moor, Cumbria-based specialist manufacturer of complex, high-tolerance aluminium extrusions holding ISO 9001 and AS 9100 certifications. The company offers a complete service from extrusion design and manufacture through to heat treatment, machining, powder coating, anodising, alocroming, polishing, linishing, screen printing, and assembly.', '{"company_type":"Extrusion","website_url":"https://capalex.co.uk/","location":"Cleator Moor, Cumbria, UK","certifications":["ISO 9001","AS9100"],"capabilities":["Custom Aluminium Extrusion","Heat Treatment","CNC Machining","Powder Coating","Anodising","Alocroming","Polishing","Screen Printing","Assembly"],"industries":["Aerospace","Defence","General Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Aluminium"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

