VALUES ('Products', 'Manufacturer', 'Smart Aluminium Extrusions Ltd', 'Smart Aluminium Extrusions Ltd is described as the UK''s largest, most modern aluminium extrusion manufacturer, based in Yatton, North Somerset, with over 40 years of experience and an annual capacity exceeding 35,000 tonnes. The company holds ISO 9001, ISO 14001, ISO 45001, ISO 50001, and BES 6001 certifications and offers bespoke extrusion, CNC machining, powder coating, and distribution services to road transport, construction, fenestration, and engineering sectors.', '{"company_type":"Extrusion","website_url":"https://smartalu.co.uk/","location":"Yatton, North Somerset, UK","certifications":["ISO 9001","ISO 14001","ISO 45001","ISO 50001","BES 6001"],"capabilities":["Aluminium Extrusion","CNC Machining","Powder Coating","Distribution"],"industries":["Road Transport","Construction","Fenestration","Engineering"],"lead_time":null,"min_order":null,"employees":"500+","established":null,"materials":["Aluminium"],"key_equipment":["Multiple Extrusion Presses"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
