VALUES ('Products', 'Manufacturer', 'Aluminium Shapes', 'Aluminium Shapes is a Northamptonshire-based aluminium extrusion manufacturer and one of only two UK-owned aluminium extrusion companies with over 25 years of operation, operating two extrusion presses with no minimum order requirement. The company holds ISO 9001 certification and provides an end-to-end service from design through extrusion, CNC machining, anodising, powder coating, assembly, and nationwide delivery via its own fleet.', '{"company_type":"Extrusion","website_url":"https://alishapes.co.uk/","location":"Northamptonshire, UK","certifications":["ISO 9001"],"capabilities":["Custom Aluminium Extrusion","CNC Machining","Powder Coating","Anodising","Assembly","Logistics"],"industries":["Manufacturing","Construction","General Engineering"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["Aluminium"],"key_equipment":["Two Extrusion Presses"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'D W Plastics Ltd', 'D W Plastics Ltd is a Chichester, West Sussex-based plastic extrusion manufacturer founded in 1980 and holding ISO 9001:2015 certification, employing 32 staff. The company designs and manufactures bespoke high-quality plastic extrusion profiles and custom tubes, pipes, and rods, with in-house die design and manufacture. Markets served include healthcare, transport, construction, safety, retail, horticulture, and sports and leisure.', '{"company_type":"Extrusion","website_url":"https://www.dwplastics.co.uk/","location":"Chichester, West Sussex, UK","certifications":["ISO 9001:2015"],"capabilities":["Custom Plastic Extrusion","Die Design & Manufacture","Tubes & Pipes","Rods","Quality Control"],"industries":["Healthcare","Transport","Construction","Safety","Retail","Horticulture","Sports"],"lead_time":null,"min_order":null,"employees":"10-49","established":1980,"materials":["PVC","ABS","HDPE","LDPE","Polycarbonate","Nylon"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
