VALUES ('Products', 'Manufacturer', 'Reddiplex Ltd', 'Reddiplex Ltd is a Droitwich, Worcestershire-based plastic and rubber extrusion manufacturer established in 1969 and holding ISO 9001 and ISO 14001 certifications. The company specialises in custom and standard plastic profiles in co-extrusion and triplex configurations, solid rubber, and sponge rubber, with in-house tooling and a wide range of secondary inline finishing capabilities. Markets served include glazing, automotive, aerospace, marine, rail, and acoustic applications.', '{"company_type":"Extrusion","website_url":"https://www.reddiplex.com/","location":"Droitwich, Worcestershire, UK","certifications":["ISO 9001","ISO 14001"],"capabilities":["Custom Plastic Extrusion","Rubber Extrusion","Co-extrusion","Triplex Extrusion","In-house Tooling","Secondary Finishing"],"industries":["Glazing","Automotive","Aerospace","Marine","Rail","Construction"],"lead_time":null,"min_order":null,"employees":null,"established":1969,"materials":["PVC","EPDM","Silicone","TPE","Rubber"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

