VALUES ('Products', 'Manufacturer', 'Nufox Rubber Limited', 'Nufox Rubber Limited is a Middleton, Manchester-based rubber extrusion manufacturer established in 1987 and holding ISO 9001:2015 and JOSCAR certifications. The company manages all production under one roof and manufactures custom rubber extrusions, profiles, gaskets, seals, mouldings, fenders, industrial inflatables, and silicone extrusions in over 15 rubber compounds. Industries served include marine, oil and gas, defence, rail, nuclear, and food and pharmaceutical.', '{"company_type":"Extrusion","website_url":"https://www.nufox.com/","location":"Middleton, Manchester, UK","certifications":["ISO 9001:2015","JOSCAR"],"capabilities":["Rubber Extrusion","Silicone Extrusion","Custom Profiles","Gaskets","Seals","Mouldings","Fenders","Industrial Inflatables"],"industries":["Marine","Oil & Gas","Defence","Rail","Nuclear","Food","Pharmaceutical","Automotive"],"lead_time":null,"min_order":null,"employees":null,"established":1987,"materials":["NBR","EPDM","Neoprene","Silicone","Polyurethane","Nitrile","Viton"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'COH Baines', 'COH Baines is a Tunbridge Wells, Kent-based rubber and plastic extrusion specialist with more than 80 years of experience, holding UKAS accreditation. The company is a market leader in rubber and plastic extrusions, sponge profiles, and PVC profiles, working with EPDM, SBR, natural rubber, silicone, neoprene, nitrile, and Viton materials. Key sectors include aerospace, automotive, construction, electronics, and marine.', '{"company_type":"Extrusion","website_url":"https://coh-baines.co.uk/","location":"Tunbridge Wells, Kent, UK","certifications":["UKAS"],"capabilities":["Rubber Extrusion","Plastic Extrusion","Sponge Profiles","PVC Profiles","Custom Mouldings"],"industries":["Aerospace","Automotive","Construction","Electronics","Marine"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["EPDM","SBR","Natural Rubber","Silicone","Neoprene","Nitrile","Viton","PVC"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'PAL Extrusions (PAL Group Operations Ltd)', 'PAL Extrusions, part of PAL Group Operations Ltd, is a Wednesbury, West Midlands-based specialist in rigid, flexible, and co-extruded thermoplastic extrusions with over 30 years of manufacturing experience and BSI ISO 9001 certification. The company develops bespoke and trade profiles including glazing seals, gaskets, and pressure plates for uPVC and aluminium window systems, electrical trunking, and specialist engineering polymers, with full in-house tooling design and production.', '{"company_type":"Extrusion","website_url":"https://www.palextrusions.co.uk/","location":"Wednesbury, West Midlands, UK","certifications":["ISO 9001"],"capabilities":["Rigid Plastic Extrusion","Flexible Plastic Extrusion","Co-extrusion","Glazing Seals","Gaskets","In-house Tooling Design"],"industries":["Fenestration","Electrical","Building Products","General Industrial"],"lead_time":null,"min_order":null,"employees":null,"established":null,"materials":["PVC","ABS","Polycarbonate","Engineering Polymers"],"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');


