VALUES ('Products', 'Manufacturer', 'FermionX Ltd', 'FermionX (formerly Tenkay Electronics) is a West Sussex-based contract electronics manufacturer with over 50 years of trading history, holding both ISO 13485 and ISO 9001 certifications. They offer a full range of services from PCB assembly and sub-assemblies through to integrated box builds, test, fulfilment, and logistics for medical, defence, marine, and automotive sectors.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.fermionx.com","location":"Worthing, West Sussex, UK","certifications":["ISO 13485","ISO 9001","IPC-A-610","IPC J-STD-001","RoHS Compliant","REACH Compliant"],"capabilities":["PCB Assembly","Sub-Assembly","Electro-Mechanical Assembly","Box Build","Testing","Supply Chain Management","Logistics & Fulfilment"],"industries":["Medical & Laboratory","Military & Defence","Marine","Automotive","Oil & Gas","Aviation","Lighting & Audio"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mi3 Limited', 'Mi3 is a Blackburn-based medical device contract manufacturer certified to ISO 13485 and audited via the Medical Device Single Audit Programme (MDSAP). They operate ISO Class 7 cleanrooms alongside controlled manufacturing environments, specialising in plastic and silicone medical device design, injection moulding, extrusion, ultrasonic welding, 3D printing, and sterile contract assembly.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.mi-3.co.uk","location":"Blackburn, Lancashire, UK","certifications":["ISO 13485:2016","MDSAP"],"capabilities":["Clean Room Assembly","Injection Moulding","Extrusion","Ultrasonic Welding","3D Printing / Prototyping","Sterilisation Services","Contract Manufacturing"],"industries":["Medical Devices","Surgical Instruments"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Thermoplastics","Silicone"],"key_equipment":["ISO Class 7 Cleanroom","Injection Moulding Machines","Extrusion Lines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Europlaz Technologies Ltd', 'Europlaz Technologies is an Essex-based ISO 13485-certified medical device contract manufacturer with over 40 years of experience and FDA registration. They operate seven ISO Class 7 cleanrooms and 24 injection moulding machines, offering injection moulding, cleanroom device assembly, and full-service project management for class I, IIa, and IIb medical devices.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://europlaz.co.uk","location":"Southminster, Essex, UK","certifications":["ISO 13485:2016","FDA Registered"],"capabilities":["Clean Room Assembly","Injection Moulding","Medical Device Assembly","Rapid Prototyping","Full-Service Project Management"],"industries":["Medical Devices"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":["Medical-Grade Polymers"],"key_equipment":["7x ISO Class 7 Cleanrooms","24x Injection Moulding Machines"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pennine Healthcare', 'Pennine Healthcare is an employee-owned Derby-based medical device manufacturer and contract manufacturer, established in 1963 and employing around 180 people. Operating 100,000 sq ft of ISO 14644 Class 8 cleanroom and controlled manufacturing space, they produce single-use sterile devices, custom procedure packs, and undertake contract manufacturing for OEMs across airway, surgical, and urology applications.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.penninehealthcare.co.uk","location":"Derby, Derbyshire, UK","certifications":["ISO 13485","ISO 14644-1 (Class 8 Cleanroom)","ISO 14001"],"capabilities":["Clean Room Assembly","Medical Device Manufacturing","Injection Moulding","Extrusion","Contract Medical Packaging","Sterile Single-Use Device Production"],"industries":["Medical Devices","Veterinary Surgical"],"lead_time":null,"min_order":null,"employees":"100-249","established":1963,"materials":null,"key_equipment":["ISO Class 8 Cleanroom (100,000 sq ft)"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Arrow Medical Limited', 'Arrow Medical is a Herefordshire-based contract manufacturer of single-use medical devices, wholly owned by Forefront Medical Technology. With over 30 years of experience and ISO 13485:2016 certification, they operate multiple cleanrooms for device assembly, silicone injection and compression moulding, tubing, and UV curing with sterile chain packaging capabilities.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://arrowmedical.co.uk","location":"Kington, Herefordshire, UK","certifications":["ISO 13485:2016"],"capabilities":["Clean Room Assembly","Silicone Injection Moulding","Plastic Injection Moulding","Medical Tubing Manufacturing","RF Welding","UV Curing","Sterile Chain Packaging","Screen Printing"],"industries":["Medical Devices","Healthcare"],"lead_time":null,"min_order":null,"employees":"50-99","established":null,"materials":["Silicone","Polyurethane","PVC"],"key_equipment":["Multiple ISO Class 7 Cleanrooms","Silicone Injection Moulding Presses"],"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'OSI Electronics (UK) Ltd', 'OSI Electronics UK, part of the global OSI Systems group, is a Cambridgeshire-based contract electronics manufacturer incorporated in 1986. Certified to ISO 9001, ISO 13485, and ISO 14001, they provide design, PCB assembly, box build, cable harnesses, sub-assembly, and optoelectronic solutions for medical, aerospace, defence, and communications markets.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.osi-electronics.uk","location":"St Neots, Cambridgeshire, UK","certifications":["ISO 9001:2015","ISO 13485:2016","ISO 14001:2015"],"capabilities":["PCB Assembly","Box Build & Sub-Assembly","Cable & Harness Assembly","Electronics Design & Engineering","Fast-Track Prototyping & NPI","Flex Circuits","Optoelectronics","Global Procurement"],"industries":["Medical & Life Sciences","Aerospace & Defence","Communications","Automotive","Security","Commercial & IoT"],"lead_time":null,"min_order":null,"employees":"100-249","established":1986,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Connect 2 Technology', 'Connect 2 Technology is a Teesside-based specialist in cable assemblies, wiring harnesses, control panels, and electronic box builds, with approximately 30 years of operating history. Certified to ISO 9001:2015 and IPC A-620, they are part of the Cleveland Technologies Group and provide end-to-end turnkey solutions serving scientific, renewables, aviation, maritime, and defence sectors across the UK.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.connect2t.co.uk","location":"Marske-by-the-Sea, Teesside, UK","certifications":["ISO 9001:2015","IPC A-620"],"capabilities":["Cable Assembly","Wiring Harness Assembly","Control Panel Build","Electronic Box Build","Fibre Optic Cables","Inspection & Bespoke Testing"],"industries":["Scientific","Renewables","Aviation","Counter Terrorism","Maritime","Fire Protection","Defence"],"lead_time":null,"min_order":null,"employees":"10-49","established":null,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kingfield Electronics Limited', 'Kingfield Electronics is a Chesterfield-based turnkey contract electronics manufacturer established in 1985, serving the aerospace, defence, marine, and industrial sectors. Certified to AS9100 and Cyber Essentials Plus, and a Make UK Defence member, they provide full turnkey PCB assembly, box build, system integration, material management, and logistics from a dedicated UK facility.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.kingfield-electronics.co.uk","location":"Chesterfield, Derbyshire, UK","certifications":["AS9100","Cyber Essentials Plus","JOSCAR"],"capabilities":["Turnkey PCB Assembly","Box Build Assembly","System Integration","Material Management","Engineering Support","Logistics"],"industries":["Aerospace","Defence","Industrial","Marine & Offshore","Transport"],"lead_time":null,"min_order":null,"employees":"50-99","established":1985,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Axiom Manufacturing Services Ltd', 'Axiom Manufacturing Services is a Newport, Wales-based contract electronics manufacturer incorporated in 1997 and specialising in low-to-medium volume, high-IP electronics for aerospace, defence, medical, and industrial markets. Holding Nadcap AC7120, AS9100, ISO 9001, ISO 14001, and IPC-A-610 approvals, they offer PCB assembly, electro-mechanical assembly, box build, system integration, and test solutions.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.axiom-ms.com","location":"Newbridge, Newport, Wales, UK","certifications":["Nadcap AC7120","AS9100","ISO 9001:2000","ISO 14001","IPC-A-610 Class 1/2/3"],"capabilities":["PCB Assembly","Electro-Mechanical Assembly","Box Build","System Integration","Test Solutions","Supply Chain Management","Design for Manufacture"],"industries":["Aerospace","Defence & Security","Medical","Industrial"],"lead_time":null,"min_order":null,"employees":"50-99","established":1997,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Stewart Technology Ltd', 'Stewart Technology is a Scottish Borders-based contract electronics manufacturer founded in 1998, employing approximately 55 staff at Tweedside Park, Galashiels. Accredited to ISO 9001 (since 1999) and ISO 13485:2016 for medical devices, they provide PCB assembly, box build, sub-assembly, and test services to IPC-A-610 Class 2 and 3 standards for medical, industrial, and defence customers.', '{"company_type":"Assembly & Contract Manufacturing","website_url":"https://www.stewart-technology.co.uk","location":"Galashiels, Scottish Borders, Scotland, UK","certifications":["ISO 9001:2015","ISO 13485:2016","IPC-A-610 Class 2 & 3"],"capabilities":["PCB Assembly","Box Build","Sub-Assembly","Testing & Inspection","Prototyping","NPI"],"industries":["Medical","Industrial","Defence","Electronics"],"lead_time":null,"min_order":null,"employees":"50-99","established":1998,"materials":null,"key_equipment":null,"data_source":"company_website","data_confidence":"high","last_verified":"2026-02"}', NULL, true, true, 'claimed');

